const GRAMMAR_DATA = [{"num": 1, "term": "-거나", "meaning": "Hoặc, hay (liệt kê các lựa chọn/hành động tương đương)", "blocks": [["p", "'-거나' có thể gắn vĩ tố thì (thì và sự hoàn thành của hành động) '-었(았, 였)-' ở phía trước, nhưng không dùng vĩ tố phỏng đoán '-겠-'. Dùng để biểu thị việc liệt kê từ hai hành động, trạng thái, sự tồn tại trở lên. Danh từ sẽ dùng dưới dạng 'Danh từ + (이)나'."], ["p", "<b>1. Trường hợp '-거나' được dùng đơn lẻ</b>"], ["ex", "내일은 <b>춥거나</b> 눈이 오겠습니다.", "Ngày mai trời sẽ lạnh hoặc có tuyết rơi."], ["ex", "일요일에 낮잠을 <b>자거나</b> 영화를 봅니다.", "Vào Chủ nhật tôi ngủ nướng hoặc xem phim."], ["p", "<b>2. Trường hợp '-거나' được lặp lại: Dùng khi liệt kê từ hai động từ trở lên có tính chất đối lập hoặc tương đương nhau.</b>"], ["ex", "일찍 <b>왔거나</b> 늦게 <b>왔거나</b> 하여튼 도착해서 다행입니다. (O)", "Dù đến sớm hay đến trễ thì dù sao cũng đã đến nơi, thật may mắn."], ["ex", "밥을 <b>먹거나</b> 빵을 <b>먹거나</b> 마음대로 하세요. (X)", "Dù ăn cơm hay ăn bánh mì thì hãy làm theo ý bạn."]], "practice": [{"vn": "Cuối tuần tôi nghỉ ở nhà hoặc gặp bạn bè.", "hint": "주말/집/쉬다/친구/만나다", "answer": "주말에는 집에서 쉬거나 친구를 만나요."}, {"vn": "Nếu có từ không biết thì hãy tra từ điển hoặc hỏi giáo viên.", "hint": "모르다/단어/있다/사전/찾다/선생님/물어보다", "answer": "모르는 단어가 있으면 사전을 찾거나 선생님께 물어보세요."}, {"vn": "Dù bận hay mệt thì tôi cũng cố gắng tập thể dục.", "hint": "바쁘다/피곤하다/운동/꼭/하다", "answer": "바쁘거나 피곤하거나 운동은 꼭 하려고 해요."}]}, {"num": 2, "term": "-거늘", "meaning": "Đương nhiên là..., huống chi (nhấn mạnh điều hiển nhiên)", "blocks": [["p", "Dùng trong trường hợp nói về thực tế ở mệnh đề trước và thể hiện mệnh đề sau cũng đương nhiên phải như vậy (mệnh đề sau thường đi kèm với '-는가?', '-(으)랴' hoặc câu hỏi), hoặc dùng để hưởng ứng theo thực tế ở mệnh đề trước. Đây là biểu hiện mang tính cổ điển/sách vở."], ["ex", "불우 이웃 돕기도 <b>하거늘</b> 하물며 가족을 안 도울 수 있겠는가?", "Đến việc giúp đỡ hàng xóm khó khăn còn làm được, huống chi lại không thể giúp đỡ gia đình mình sao?"], ["ex", "남의 자식도 <b>귀엽거늘</b> 자기 자식이면 얼마나 귀여울까?", "Con cái nhà người khác còn thấy đáng yêu, huống chi là con của chính mình thì đáng yêu biết chừng nào?"]], "practice": [{"vn": "Động vật còn yêu thương con cái, huống chi con người thì khỏi phải nói.", "hint": "동물/자식/사랑하다/하물며/사람/말하다", "answer": "동물도 자식을 사랑하거늘 하물며 사람이야 말할 것도 없다."}, {"vn": "Người lớn còn mắc lỗi, huống chi trẻ con mắc lỗi thì có gì lạ?", "hint": "어른/실수/하다/아이/당연하다", "answer": "어른도 실수를 하거늘 아이가 실수하는 건 당연하지 않겠는가?"}, {"vn": "Người giàu còn sống tiết kiệm, huống chi người như chúng ta thì khỏi phải nói.", "hint": "부자/아끼다/살다/우리/사람/말하다", "answer": "부자도 아끼며 살거늘 우리 같은 사람이야 말할 것도 없다."}]}, {"num": 3, "term": "-거니와", "meaning": "Không những... mà còn... (vừa công nhận vế trước, vừa bổ sung thêm vế sau)", "blocks": [["p", "<b>1.</b> Dùng khi vừa công nhận nội dung ở mệnh đề trước, vừa bổ sung thêm thực tế ở mệnh đề sau. Thường dùng khi muốn nói rằng không chỉ có thực tế ở mệnh đề trước mà còn thêm cả thực tế ở mệnh đề sau nữa nên càng như thế nào đó."], ["ex", "그는 열심히 <b>일하거니와</b> 운도 좋아서 하는 일마다 성공을 거두었다.", "Anh ấy không những làm việc chăm chỉ mà may mắn cũng tốt nên làm việc gì cũng thu được thành công."], ["ex", "정은이는 얼굴도 <b>예쁘거니와</b> 마음씨까지 착해서 인기가 최고다.", "Jung-eun không những có khuôn mặt đẹp mà tấm lòng cũng tốt nên rất được yêu thích."], ["p", "<b>2.</b> [Gắn vào các từ như '다시 말하다' (nói lại), '다시 설명하다' (giải thích lại), '거듭 덧붙이다' (thêm vào đó)], dùng để thể hiện việc nhắc lại một lần nữa nội dung có liên quan đến thực tế ở mệnh đề sau."], ["ex", "다시 한번 <b>말하거니와</b> 이번 시험은 매우 중요합니다.", "Tôi xin nói lại một lần nữa, kỳ thi lần này vô cùng quan trọng."], ["ex", "거듭 <b>덧붙이거니와</b> 오늘은 절대로 늦으시면 안 됩니다.", "Tôi xin nhấn mạnh thêm, hôm nay tuyệt đối không được đến trễ."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-았거니와' và '-겠거니와'</b>", "<b>1. -았거니와:</b> Dùng khi nói về việc đã kết thúc hoặc sự việc trong", "quá khứ."]], ["ex", "그는 열심히 <b>했거니와</b> 운도 좋아서 하는 일마다 성공을 거두었다.", "Anh ấy không những đã làm việc chăm chỉ mà may mắn cũng tốt nên làm việc gì cũng thành công."], ["ex", "부모님도 <b>돌아가셨거니와</b> 하나 남은 동생마저 얼마 전에 죽었다.", "Bố mẹ không những đã qua đời mà ngay cả người em duy nhất còn lại cũng mới mất cách đây không lâu."], ["bq", ["<b>2. -겠거니와:</b> Dùng khi muốn thể hiện tương lai hoặc ý chí."]], ["ex", "대학에도 <b>가겠거니와</b> 공부를 열심히 해서 은혜를 갚겠습니다.", "Tôi không những sẽ vào đại học mà còn sẽ học tập chăm chỉ để đáp lại ơn nghĩa."], ["ex", "승화를 보려고 전화도 <b>하겠거니와</b> 직접 찾아가서 만나자고 할 것이다.", "Để gặp Seung-hwa, anh ấy không những sẽ gọi điện mà chắc chắn sẽ trực tiếp tìm đến gặp."]], "practice": [{"vn": "Diễn viên đó không những diễn xuất giỏi mà khả năng ca hát cũng xuất sắc.", "hint": "배우/연기/잘하다/노래/실력/뛰어나다", "answer": "그 배우는 연기도 잘하거니와 노래 실력도 뛰어나다."}, {"vn": "Quán này không những giá rẻ mà còn ngon nên đông khách.", "hint": "식당/값/싸다/맛/좋다/손님/많다", "answer": "이 식당은 값도 싸거니와 맛도 좋아서 손님이 많다."}, {"vn": "Tôi xin nhấn mạnh lại một lần nữa, an toàn là điều quan trọng nhất.", "hint": "다시/한번/강조하다/안전/가장/중요하다", "answer": "다시 한번 강조하거니와 안전이 가장 중요합니다."}]}, {"num": 4, "term": "-거든", "meaning": "Nếu... thì (điều kiện, thường dùng khi vế sau là đề nghị/mệnh lệnh/câu hỏi)", "blocks": [["p", "<b>1.</b> Mang ý nghĩa \"Nếu nội dung trước là sự thật hoặc trở thành sự thật\"."], ["ex", "어려운 일이 <b>생기거든</b> 언제든지 연락 주십시오.", "Nếu có việc gì khó khăn phát sinh, hãy liên lạc cho tôi bất cứ lúc nào."], ["ex", "고향에 <b>가거든</b> 선생님께 이 편지를 꼭 전해 주세요.", "Nếu có về quê, nhất định hãy chuyển lá thư này cho thầy/cô nhé."], ["p", "<b>2.</b> Dùng khi nội dung ở mệnh đề trước là như vậy nên nội dung ở mệnh đề sau đương nhiên cũng là sự thật."], ["ex", "언니가 저토록 <b>지혜롭거든</b>, 동생이야 더 말할 것도 없다.", "Chị gái mà thông minh đến nhường ấy thì em gái lại càng không cần phải nói thêm nữa."], ["ex", "고슴도치도 제 자식은 예쁘다고 <b>하거든</b>, 하물며 사람이야.", "Ngay cả con nhím còn thấy con mình đẹp, huống chi là con người."], ["bq", ["<b>Tìm hiểu thêm | Vĩ tố kết thúc câu '-거든'</b>", "'-거든' còn được dùng như một vĩ tố kết thúc câu nhằm đưa ra nguyên", "nhân hoặc căn cứ mà người nói nghĩ như vậy về nội dung ở mệnh đề", "trước, hoặc đưa ra tiền đề cho nội dung tiếp theo."]], ["ex", "강아지가 많이 아픈가 봐. 밥을 이렇게 많이 <b>남겼거든</b>.", "Có vẻ chú chó bị đau nhiều lắm. Nó đã bỏ lại nhiều cơm thế này cơ mà."], ["ex", "어제 백화점에서 옷을 <b>샀거든</b>. 그런데 오늘 보니까 더 싸게 팔더라고.", "Hôm qua tôi đã mua áo ở trung tâm thương mại đấy. Nhưng hôm nay xem lại thấy người ta bán rẻ hơn."]], "practice": [{"vn": "Nếu có thời gian thì tối nay cùng đi xem phim nhé.", "hint": "시간/있다/저녁/같이/영화/보다/가다", "answer": "시간이 있거든 저녁에 같이 영화 보러 가요."}, {"vn": "Nếu bị lạc đường thì hãy gọi điện cho tôi.", "hint": "길/잃다/저/전화하다", "answer": "길을 잃거든 저한테 전화하세요."}, {"vn": "Nếu trời mưa thì hãy hoãn buổi dã ngoại sang tuần sau.", "hint": "비/오다/소풍/다음 주/미루다", "answer": "비가 오거든 소풍을 다음 주로 미룹시다."}]}, {"num": 5, "term": "-건대", "meaning": "Nghĩ rằng..., cho rằng... (nêu căn cứ/suy đoán của người nói cho đề nghị/mệnh lệnh ở sau, văn viết)", "blocks": [["p", "[Gắn vào một số động từ] Là biểu hiện thông báo trước rằng người nói sắp nói ra suy nghĩ hoặc mong muốn của mình ở mệnh đề sau."], ["p", "<b>1.</b> [Gắn vào các động từ như '생각하다' (suy nghĩ), '추측하다' (dự đoán), '보다' (thấy)] Dùng để thông báo trước rằng người nói sắp nói ra suy nghĩ hoặc quan điểm của mình. Tức là thể hiện nội dung mệnh đề sau chính là suy nghĩ của người nói."], ["ex", "제가 <b>생각하건대</b> 이 음식이 가장 맛있습니다.", "Theo suy nghĩ của tôi thì món ăn này là ngon nhất."], ["ex", "제가 <b>짐작하건대</b> 누군가가 우리 일을 방해하는 게 분명합니다.", "Theo đoán chừng của tôi thì rõ ràng là có ai đó đang cản trở công việc của chúng ta."], ["p", "<b>2.</b> [Gắn vào các động từ như '바라다' (mong muốn), '부탁하다' (nhờ vả), '기대하다' (kỳ vọng)] Thể hiện người nói mong muốn hoặc nhờ vả nội dung ở mệnh đề sau."], ["ex", "<b>바라건대</b> 이번 모임에 꼭 참석해 주십시오.", "Rất mong mọi người sẽ nhất định tham dự buổi gặp mặt lần này."], ["ex", "<b>당부하건대</b> 앞으로 공부를 열심히 하세요.", "Tôi xin dặn dò/nhắc nhở là từ nay về sau hãy học tập thật chăm chỉ."], ["bq", ["<b>Tìm hiểu thêm | Dạng rút gọn của '-하건대'</b>", "Rút gọn '-하건대' có thể viết thành <b>'-건대'</b> hoặc <b>'-건대'</b>."]], ["ex", "<b>부탁건대</b> 앞으로 공부를 열심히 하세요.", "Xin nhờ rằng từ nay hãy học hành chăm chỉ."], ["ex", "<b>원건대</b> 저희 편을 응원해 주세요.", "Mong rằng hãy ủng hộ cho phe chúng tôi."], ["ex", "<b>회상건대</b> 우리가 같이 일했을 때가 좋았어요.", "Nhớ lại thì thời gian chúng ta cùng làm việc với nhau thật đẹp."]], "practice": [{"vn": "Nếu nghĩ rằng tình hình gấp thì mong bạn liên lạc trước.", "hint": "사정/급하다/먼저/연락/바라다", "answer": "사정이 급하건대 먼저 연락을 주시기 바랍니다."}, {"vn": "Theo tôi nghĩ thì cách này là tốt nhất, hãy thử một lần xem.", "hint": "생각/방법/최선이다/한번/시도하다", "answer": "내 생각으로는 이 방법이 최선이건대 한번 시도해 봅시다."}, {"vn": "Mong rằng anh/chị luôn khỏe mạnh, tôi sẽ thường xuyên liên lạc.", "hint": "몸/건강히/잘 지내다/자주/연락드리다", "answer": "부디 몸 건강히 잘 지내시건대 자주 연락드리겠습니다."}]}, {"num": 6, "term": "-건만", "meaning": "Nhưng, thế mà (nêu thực tế vế trước, nhưng vế sau lại trái ngược, không như mong đợi)", "blocks": [["p", "Thể hiện việc xảy ra nội dung, tình huống hoặc kết quả trái ngược với thực tế mà mệnh đề trước biểu thị."], ["ex", "그는 열심히 공부하기는 <b>하건만</b> 한국말을 잘 못 해요.", "Anh ấy thì đúng là học hành chăm chỉ thật đấy nhưng lại không giỏi tiếng Hàn."], ["ex", "물건은 <b>좋건만</b> 값이 비싸서 살 수 없어요.", "Hàng hóa thì tốt đấy nhưng giá đắt nên không thể mua được."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-았건만', '-겠건만' và '-지만'</b>", "<b>1.</b> Khi thể hiện việc đã hoàn thành, dùng thì quá khứ '-았/었-'", "ghép thành <b>'-았건만'</b>."]], ["ex", "한 시간이나 <b>기다렸건만</b> 경아는 오지 않았다.", "Đã đợi suốt một tiếng đồng hồ rồi nhưng Gyeong-ah vẫn không đến."], ["ex", "한국에 삼 년이나 <b>살았건만</b> 한국말을 하지 못한다.", "Đã sống ở Hàn Quốc tới 3 năm rồi nhưng vẫn không nói được tiếng Hàn."], ["bq", ["<b>2.</b> Khi thể hiện ý nghĩa ý chí hoặc dự đoán, dùng <b>'-겠건만'</b>."]], ["ex", "도와 달라고 하면 도와 <b>주겠건만</b> 통 말이 없네요.", "Nếu bảo giúp thì tôi đã giúp rồi nhưng đằng này chẳng thấy nói năng gì cả."], ["ex", "그때 출발했으면 벌써 <b>도착했겠건만</b> 아직 오지 않았습니다.", "Nếu xuất phát lúc đó thì chắc giờ đã đến nơi rồi nhưng hiện vẫn chưa tới."], ["bq", ["<b>3.</b> '-건만' có thể thay đổi bằng <b>'-지만'</b>, và thông thường", "'-지만' được sử dụng nhiều hơn."]], ["ex", "그는 일을 열심히 하기는 <b>하지만</b> 성과가 별로 없다.", "Anh ấy làm việc chăm chỉ thật đấy nhưng thành quả chẳng có bao nhiêu."], ["ex", "한국에 삼 년이나 <b>살았지만</b> 한국말을 하지 못한다.", "Tuy đã sống ở Hàn Quốc 3 năm nhưng không nói được tiếng Hàn."]], "practice": [{"vn": "Đã học chăm chỉ vậy mà kết quả lại không tốt.", "hint": "열심히/공부하다/결과/좋다", "answer": "열심히 공부했건만 결과가 좋지 않았다."}, {"vn": "Có người tiền nhiều mà lại không hạnh phúc.", "hint": "돈/많다/행복하다/사람", "answer": "돈은 많건만 행복하지 않은 사람들이 있다."}, {"vn": "Đã hẹn rồi mà anh ấy lại không xuất hiện.", "hint": "약속/하다/그/나타나다", "answer": "약속을 했건만 그는 나타나지 않았다."}]}, {"num": 7, "term": "-게", "meaning": "Để, sao cho (mục đích, tiêu chuẩn); hoặc dùng thành '-게 하다' để chỉ sự sai khiến", "blocks": [["h4", "1. Vĩ tố nối phụ thuộc"], ["p", "[Gắn vào động từ, '있다/없다'] Thể hiện mệnh đề trước trở thành mục đích, tiêu chuẩn,... cho mệnh đề sau. Mang ý nghĩa '~하도록' (để/sao cho), '~할 수 있도록' (để có thể), '-게끔'."], ["ex", "친구들과 함께 먹을 수 <b>있게</b> 과자를 많이 만들자.", "Hãy làm nhiều bánh kẹo để có thể ăn cùng các bạn nào."], ["ex", "부모님이 깨시지 <b>않게</b> 조용조용 방으로 들어갔다.", "Tôi đã đi vào phòng thật nhẹ nhàng để bố mẹ không bị thức giấc."], ["h4", "2. Vĩ tố nối bổ trợ"], ["p", "① [Gắn sau dũng từ chỉ hành động] Dùng kết hợp thành dạng '-게 하다', '-게 만들기' để thể hiện <b>sự sai khiến (사동)</b>. Mang ý nghĩa '누가 무엇을 하도록 시키다' (bắt/khiến ai đó làm gì)."], ["ex", "어머니는 내가 어릴 때부터 피아노를 <b>치게 하셨다</b>.", "Mẹ tôi đã bắt tôi chơi đàn piano từ khi tôi còn nhỏ."], ["ex", "친구를 앉아서 <b>기다리게 한다</b>.", "Bắt bạn phải ngồi chờ đợi."], ["p", "② [Dùng dưới dạng '-게 하다', '-게 만들기'] Thể hiện việc dẫn đến một tình huống như vậy."], ["ex", "<b>놀라게 해서</b> 미안합니다.", "Xin lỗi vì đã làm bạn ngạc nhiên."], ["ex", "나는 아버지를 <b>기쁘게 해</b> 드리고 싶었다.", "Tôi đã muốn làm cho bố được vui lòng."], ["p", "③ [Dùng dưới dạng '-게 되다'] Thể hiện việc dẫn đến một tình huống như vậy."], ["ex", "회사가 문을 <b>닫게 되었거든요</b>.", "Công ty đã bị đóng cửa rồi đấy."], ["ex", "풀이 <b>누렇게 되었다</b>.", "Cỏ đã bị úa vàng."], ["h4", "3. Chức năng phó từ"], ["p", "① Thể hiện việc người nói nghĩ rằng sự việc là như vậy. Mang ý nghĩa '-다고' (rằng/cho là)."], ["ex", "주영이는 사람들을 <b>가볍게</b> 여긴다.", "Ju-yeong coi thường người khác."], ["ex", "나이를 먹어 갈수록 아내가 <b>소중하게</b> 느껴진다.", "Càng nhiều tuổi, tôi càng cảm thấy vợ mình quý giá/trân trọng hơn."], ["p", "② [Gắn vào tính từ hoặc tự động từ] Thể hiện mức độ, phương thức."], ["ex", "나는 목을 <b>길게</b> 뺐다.", "Tôi đã kéo dài cổ ra (dài cổ chờ đợi)."], ["ex", "눈이 <b>부시게</b> 푸르른 날.", "Một ngày bầu trời xanh đến chói mắt."], ["h4", "4. Cách dùng vĩ tố kết thúc câu (종결 어미의 용법)"], ["p", "① Thể hiện ý nghĩa của '-(으)ㄹ 수 있도록' (để có thể...)."], ["ex", "음식 좀 많이 만들어, 여러 사람이 먹을 수 <b>있게</b>.", "Hãy làm nhiều thức ăn một chút, để nhiều người cùng ăn được."], ["p", "② Kết thúc câu với thái độ thể hiện sự bất mãn của người nói về nội dung câu nói."], ["ex", "웃기지 마, <b>유치하게</b>.", "Đừng có nực cười thế, trẻ con quá đấy."]], "practice": [{"vn": "Hãy tắt đèn để cho đứa trẻ ngủ ngon.", "hint": "아이/잘 자다/불/끄다", "answer": "아이가 잘 잘 수 있게 불을 꺼 주세요."}, {"vn": "Em tôi đã làm cho tôi tức giận.", "hint": "동생/나/화나다/만들다", "answer": "동생은 나를 화나게 만들었다."}, {"vn": "Mẹ đã bắt tôi viết nhật ký mỗi ngày.", "hint": "엄마/매일/일기/쓰다", "answer": "엄마는 내가 매일 일기를 쓰게 하셨다."}]}, {"num": 8, "term": "-게끔", "meaning": "Để, sao cho (mục tiêu/điều kiện cho hành động phía sau — tương tự '-게')", "blocks": [["p", "Thể hiện mệnh đề trước trở thành mục tiêu, lý do, điều kiện cho hành động hoặc trạng thái phía sau."], ["ex", "부모님이 <b>안심하게끔</b> 말씀드렸다.", "Tôi đã nói chuyện để bố mẹ được yên tâm."], ["ex", "내가 능력을 <b>발휘하게끔</b> 뒷받침을 해 주세요.", "Xin hãy hỗ trợ để tôi có thể phát huy năng lực của mình."], ["ex", "강에서 물고기들이 살 수 <b>있게끔</b> 깨끗하게 합시다.", "Chúng ta hãy giữ gìn dòng sông sạch sẽ để cá có thể sinh sống được."]], "practice": [{"vn": "Hãy giải thích chi tiết để tất cả mọi người có thể hiểu.", "hint": "모두/이해하다/자세히/설명하다", "answer": "모두가 이해할 수 있게끔 자세히 설명해 주세요."}, {"vn": "Tôi luôn theo dõi để bọn trẻ được an toàn.", "hint": "아이들/안전하다/늘/지켜보다", "answer": "아이들이 안전하게끔 늘 지켜보고 있어요."}, {"vn": "Hãy xuất phát sớm để không bị trễ.", "hint": "늦다/일찍/출발하다", "answer": "늦지 않게끔 일찍 출발합시다."}]}, {"num": 9, "term": "-고 해서", "meaning": "Vì... nên (nêu lý do một cách nhẹ nhàng, không chắc chắn hoàn toàn)", "blocks": [["p", "<b>1.</b> Thể hiện nội dung ở mệnh đề trước là một trong số vài lý do thực hiện hành động ở mệnh đề sau."], ["ex", "새 학기도 <b>시작했고 해서</b> 한국어 공부를 시작했다.", "Học kỳ mới cũng đã bắt đầu rồi nên tôi đã bắt đầu học tiếng Hàn."], ["ex", "내가 집에서 <b>맏딸이고 해서</b> 늘 어머니를 돕고 있다.", "Vì tôi là con gái lớn trong nhà nên luôn giúp đỡ mẹ."], ["p", "<b>2.</b> [Dùng dưới dạng '-고 -고 해서'] Dùng khi liệt kê từ hai lý do trở lên trong số nhiều lý do dẫn đến hành động ở mệnh đề sau."], ["ex", "손님도 <b>오시고</b> 집에 음식도 <b>없고 해서</b> 시장에 갔다 왔어요.", "Khách cũng đến mà ở nhà lại không có thức ăn nên tôi đã đi chợ về."], ["ex", "배도 <b>고프고</b> 목도 <b>마르고 해서</b> 하던 일을 멈추고 밖으로 나갔다.", "Bụng thì đói mà cổ lại khô nên tôi đã dừng công việc đang làm lại và đi ra ngoài."]], "practice": [{"vn": "Vì trời cũng lạnh nên hôm nay tôi định ở nhà.", "hint": "날씨/춥다/오늘/집/있다", "answer": "날씨도 춥고 해서 오늘은 집에 있으려고요."}, {"vn": "Vì cũng đói bụng nên chúng ta đi ăn gì đó nhé.", "hint": "배/고프다/뭐/먹다/가다", "answer": "배도 고프고 해서 우리 뭐 좀 먹으러 갑시다."}, {"vn": "Vì cũng đã muộn rồi nên hôm nay kết thúc ở đây thôi.", "hint": "시간/늦다/오늘/여기/끝내다", "answer": "시간도 늦고 해서 오늘은 여기서 끝냅시다."}]}, {"num": 10, "term": "-고도", "meaning": "Mặc dù... nhưng, dù đã... nhưng (nhượng bộ)", "blocks": [["p", "Thể hiện sự đối lập với thực tế hay cảm xúc ở mệnh đề trước, hoặc tiếp nối thêm một đặc tính khác."], ["ex", "그렇게 혼이 <b>나고도</b> 아직 정신을 못 차렸다.", "Bị mắng/bị mắng cho một trận như thế rồi mà vẫn chưa tỉnh ngộ ra."], ["ex", "정은이는 일을 <b>망치고도</b> 책임을 지지 않는다.", "Jeong-eun làm hỏng việc rồi mà lại không chịu trách nhiệm."], ["bq", ["<b>Tìm hiểu thêm | Thì (시제) của '-고도'</b>", "Trước '-고도' không được sử dụng các vĩ tố chỉ quá khứ như '-았/었-'", "hoặc chỉ tương lai như '-겠-'."]], ["ex", "그는 실수를 <b>하고도</b> 사과하지 않았다. (O)", "Anh ấy phạm lỗi rồi mà không xin lỗi."], ["ex", "그는 실수하였고도 사과하지 않았다. (X)", ""], ["ex", "그는 <b>떠나고도</b> 연락하지 않을 것이다. (O)", "Dù anh ấy có rời đi thì cũng sẽ không liên lạc đâu."], ["ex", "그는 떠나겠고도 연락하지 않을 것이다. (X)", ""]], "practice": [{"vn": "Bộ quần áo này dù đắt nhưng chất lượng không tốt lắm.", "hint": "옷/비싸다/품질/별로/좋다", "answer": "이 옷은 비싸고도 품질이 별로 안 좋아요."}, {"vn": "Anh ấy dù có nhiều tiền nhưng luôn sống giản dị.", "hint": "돈/많다/항상/검소하다/살다", "answer": "그는 돈이 많고도 항상 검소하게 산다."}, {"vn": "Dù đã uống thuốc rồi nhưng cảm vẫn chưa khỏi.", "hint": "약/먹다/감기/낫다", "answer": "약을 먹고도 감기가 낫지 않았다."}]}, {"num": 11, "term": "-고서", "meaning": "...xong rồi mới... (hành động trước hoàn tất rồi mới thực hiện hành động sau)", "blocks": [["p", "Thể hiện từ hai hành động trở lên xảy ra theo thứ tự thời gian."], ["p", "<b>1.</b> Dùng khi hành động xảy ra trước về mặt thời gian đứng trước, hành động xảy ra sau đứng ở mệnh đề sau. Trường hợp này có thể thay thế thành '-고' và '-고 나서'."], ["ex", "손을 <b>씻고서</b> 밥을 먹어라.", "Hãy rửa tay rồi ăn cơm đi."], ["ex", "수연이가 <b>떠나고 나서</b> 누리도 떠났다.", "Su-yeon rời đi rồi Nuri cũng rời đi."], ["p", "<b>2.</b> Thể hiện trạng thái hoặc kết quả của hành동 phía trước được duy trì trong khi hành động phía sau tiến hành."], ["ex", "무거운 가방을 <b>들고서</b> 갔어요.", "Tôi đã xách/mang cái túi nặng rồi đi."], ["ex", "코트를 <b>입고서</b> 춥다고 한다.", "Mặc áo khoác vào rồi lại kêu lạnh."], ["p", "<b>3.</b> Trong trường hợp nhiều hành động tiếp nối nhau, hành động phía trước chỉ dùng '-고', và chỉ hành động cuối cùng mới dùng '-고서'."], ["ex", "장갑을 끼고 목도리를 <b>하고서</b> 나가라.", "Hãy đeo găng tay, quàng khăn cổ rồi đi ra ngoài."], ["ex", "청소를 하고 빨래를 <b>하고서</b> 쉬었습니다.", "Tôi dọn dẹp, giặt giũ rồi nghỉ ngơi."]], "practice": [{"vn": "Hãy rửa tay xong rồi mới ăn cơm.", "hint": "손/씻다/밥/먹다", "answer": "손을 씻고서 밥을 먹읍시다."}, {"vn": "Tôi sẽ làm xong bài tập rồi mới xem tivi.", "hint": "숙제/다/하다/텔레비전/보다", "answer": "숙제를 다 하고서 텔레비전을 볼게요."}, {"vn": "Suy nghĩ kỹ xong rồi mới đưa ra quyết định.", "hint": "충분히/생각하다/결정/내리다", "answer": "충분히 생각하고서 결정을 내렸다."}]}, {"num": 12, "term": "-고자", "meaning": "Để, với ý định (mục đích, thường dùng trong văn viết trang trọng)", "blocks": [["p", "Là biểu hiện trang trọng của '-(으)려고'. Chủ yếu được dùng trong văn viết, bài phát biểu, phỏng vấn, v.v."], ["p", "<b>1. Trường hợp '-고자 하다' được dùng như một biểu hiện cố định:</b>"], ["ex", "저는 1년 동안 한국어를 <b>배우고자 합니다</b>.", "Tôi muốn/có ý định học tiếng Hàn trong 1 năm."], ["ex", "이번 설날에 고향에 <b>돌아가고자 합니다</b>.", "Tết này tôi muốn/có ý định trở về quê hương."], ["p", "<b>2. Trường hợp '-고자 + Động từ khác':</b>"], ["ex", "친구에게 <b>주고자</b> 책을 샀습니다.", "Tôi đã mua sách để tặng cho bạn."], ["ex", "일찍 <b>일어나고자</b> 일찍 자갑니다.", "Tôi đi ngủ sớm để thức dậy sớm."], ["ex", "한국어를 <b>배우고자</b> 한국에 왔습니다.", "Tôi đã đến Hàn Quốc để học tiếng Hàn."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-고자' và '-(으)러'</b>", "Ý nghĩa cơ bản giống nhau nhưng mệnh đề theo sau có sự khác biệt nhỏ.", "<b>1. -고자:</b> Thể hiện việc mang một mục đích, ý định, hy vọng nào đó.", "Mệnh đề sau có thể đi cùng dạng mệnh lệnh (명령형) hoặc rủ rê", "(청유형)."]], ["ex", "남에게 존중을 <b>받고자</b> 한다면 먼저 남을 존중해야 한다. (명령형, 청유형 가능)", "Nếu muốn nhận sự tôn trọng từ người khác thì trước tiên phải tôn trọng người khác.) <i>→ 남에게 존중을 <b>받고자</b> 한다면 먼저 남을 존중하라/존중하자. </i>(Nếu muốn nhận sự tôn trọng từ người khác thì hãy tôn trọng / cùng tôn trọng người khác trước tiên. - Có thể dùng câu mệnh lệnh, rủ rê"], ["bq", ["<b>2. -(으)러:</b> Thể hiện mục đích của các hành động di chuyển như", "\"đi\" hoặc \"đến\". Mệnh đề sau không thể đi cùng dạng mệnh lệnh hoặc", "rủ rê."]], ["ex", "그녀는 내일 건강 검진을 <b>받으러</b> 병원에 갈 예정이다. 청유형 불가능)", "Cô ấy dự định đến bệnh viện để khám sức khỏe vào ngày mai.) <i>→ 그녀는 내일 건강 검진을 <b>받으러</b> 병원에 가라/가자. (명령형, </i>(Không thể dùng câu mệnh lệnh, rủ rê"]], "practice": [{"vn": "Chúng tôi đã mở cuộc họp để giải quyết vấn đề này.", "hint": "문제/해결하다/회의/열다", "answer": "이 문제를 해결하고자 회의를 열었습니다."}, {"vn": "Chúng tôi đã chuẩn bị sự kiện này để giới thiệu văn hóa Hàn Quốc.", "hint": "한국/문화/알리다/행사/준비하다", "answer": "한국 문화를 알리고자 이 행사를 준비했습니다."}, {"vn": "Tôi có ý định đi du học vào năm sau.", "hint": "내년/유학/가다", "answer": "저는 내년에 유학을 가고자 합니다."}]}, {"num": 23, "term": "-다가는/다간", "meaning": "Cứ... thì (cảnh báo về kết quả xấu nếu tiếp tục hành động)", "blocks": [["p", "Dùng khi lo lắng về một kết quả xấu nên cảnh báo hoặc cẩn trọng. '-다간' là dạng rút gọn của '-다가는'."], ["p", "<b>1. Dự đoán rằng nếu cứ thực hiện hành động ở mệnh đề trước nhiều lần thì có thể sẽ dẫn đến kết quả xấu.</b>"], ["ex", "그렇게 <b>놀다가는</b> 시험에서 떨어질 텐데.......", "Cứ chơi bời như thế thì chắc là sẽ trượt kỳ thi mất......."], ["ex", "저렇게 사탕을 많이 <b>먹다가는</b> 이가 썩을 거예요.", "Cứ ăn nhiều kẹo như thế kia thì sẽ bị sâu răng đấy."], ["ex", "담배를 계속 <b>피우다간</b> 건강이 나빠질 거예요.", "Cứ tiếp tục hút thuốc thì sức khỏe sẽ xấu đi đấy."], ["p", "<b>2. Thể hiện khi thực hiện hành động ở mệnh đề trước thì kết quả ở mệnh đề sau thường xuất hiện như một lẽ thông thường.</b>"], ["ex", "술을 마시고 <b>운전하다가는</b> 사고가 나요.", "Uống rượu rồi lái xe thì sẽ xảy ra tai nạn."], ["ex", "엄마한테 자주 거짓말을 <b>하다간</b> 야단맞아요.", "Cứ thường xuyên nói dối mẹ thì sẽ bị mắng đấy."], ["ex", "도둑질을 <b>하다간</b> 감옥에 가요.", "Trộm cắp thì sẽ phải đi tù."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-다가는', '-다 보면', '-다 보니(까)'</b>"]], ["p", "+---------+---------------------+-------------------+-----------------+ | > <b>Cấu | > </b>Sự việc ở mệnh  | > <b>Kết quả ở     | > </b>Thái độ đối | | >       | > đề trước<b>        | > mệnh đề sau</b>   | > với kết quả<b> | |  trúc</b> |                     |                   |                 | +=========+=====================+===================+=================+ | > <b>-다 | > Xảy ra nhiều lần  | > Kết quả không   | > Dự đoán kết   | | 가는</b>  | > (Tần suất)        | > tốt             | > quả xấu       | +---------+---------------------+-------------------+-----------------+ | > <b>-다 | > Xảy ra liên tục   | > Kết quả tốt     | > Nói bằng cách | | >       | > (Lưu xót/Tăng     | > hoặc Kết quả    | > dự đoán kết   | |  보면</b> | > tiến)             | > không tốt       | > quả           | +---------+---------------------+-------------------+-----------------+ | > <b>-다 | > Xảy ra liên tục   | > Kết quả tốt     | > Nói về kết    | | > 보니  | > (Lưu xót/Tăng     | > hoặc Kết quả    | > quả đã xuất   | | (까)</b>  | > tiến)             | > không tốt       | > hiện          | +---------+---------------------+-------------------+-----------------+"]], "practice": [{"vn": "Cứ chơi bời như thế thì chắc là sẽ trượt kỳ thi mất.", "hint": "그렇게/놀다/시험/떨어지다", "answer": "그렇게 놀다가는 시험에서 떨어질 텐데......."}, {"vn": "Cứ đi trễ liên tục thì có thể sẽ bị công ty đuổi việc đấy.", "hint": "자꾸/지각하다/회사/잘리다", "answer": "자꾸 지각하다가는 회사에서 잘릴지도 몰라요."}, {"vn": "Cứ lái xe quá tốc độ thì có thể xảy ra tai nạn lớn.", "hint": "과속/운전하다/큰/사고/나다", "answer": "과속으로 운전하다가는 큰 사고가 날 수 있어요."}]}, {"num": 24, "term": "-다마는/다만", "meaning": "...nhưng, ...song (thừa nhận điều vế trước nhưng vế sau có phần trái ngược/giới hạn)", "blocks": [["p", "<b>1. Dùng khi công nhận một thực tế hay nội dung nào đó, nhưng bổ sung thêm nội dung trái ngược với nó.</b>"], ["ex", "네 처지는 <b>안타깝다마는</b> 내가 도와줄 수가 없구나.", "Hoàn cảnh của cháu thật đáng tiếc nhưng ta lại không thể giúp được gì."], ["ex", "집이 아주 <b>좋다마는</b> 우리 형편에는 안 맞는 것 같구나.", "Căn nhà thì rất tốt đấy nhưng có vẻ không phù hợp với hoàn cảnh của chúng ta."], ["p", "<b>2. '-다마는' có thể rút gọn thành '-다만'.</b>"], ["ex", "네 처지는 <b>안타깝다만</b> 내가 도와줄 수가 없구나.", "Hoàn cảnh của cháu thật đáng tiếc nhưng ta lại không thể giúp được gì."], ["ex", "집이 아주 <b>좋다만</b> 우리 형편에는 안 맞는 것 같구나.", "Căn nhà thì rất tốt đấy nhưng có vẻ không phù hợp với hoàn cảnh của chúng ta."]], "practice": [{"vn": "Tôi muốn ăn nhưng vì đang ăn kiêng nên đã nhịn.", "hint": "먹다/싶다/다이어트/중/참다", "answer": "먹고 싶다마는 다이어트 중이라서 참았어요."}, {"vn": "Tôi muốn đi nhưng vì không có thời gian nên không đi được.", "hint": "가다/싶다/시간/없다", "answer": "가고 싶다마는 시간이 없어서 못 가요."}, {"vn": "Tốt thì tốt đấy nhưng giá quá đắt nên không mua nổi.", "hint": "좋다/가격/너무/비싸다/사다", "answer": "좋다마는 가격이 너무 비싸서 못 사겠어요."}]}, {"num": 25, "term": "-다면", "meaning": "Nếu... thì (giả định)", "blocks": [["p", "<b>1. Giả định về một việc không chắc chắn. Không phù hợp khi dùng cho việc xảy ra mang tính thông thường hoặc lặp đi lặp lại.</b>"], ["ex", "만약 복권에 <b>당첨된다면</b> 차를 사겠어요.", "Nếu trúng số thì tôi sẽ mua xe ô tô."], ["ex", "만일 회사에서 <b>승진한다면</b> 한턱낼게요.", "Nếu được thăng chức ở công ty thì tôi sẽ khao một chấu."], ["ex", "만약 책을 다 <b>읽는다면</b> 좀 빌려주세요.", "Nếu đọc xong sách thì hãy cho tôi mượn nhé."], ["ex", "만일 모르는 것이 <b>있다면</b> 질문하세요.", "Nếu có chỗ nào không biết thì hãy hỏi nhé."], ["p", "<b>2. Hy vọng, mong ước: Dạng '-다면 좋겠다' có khả năng thực hiện thấp hơn so với '-(으)면 좋겠다'.</b>"], ["p", "① <b>Mong ước của bản thân</b>"], ["ex", "저는 이번 방학 때 <b>여행간다면</b> 좋겠어요.", "Kỳ nghỉ lần này nếu được đi du lịch thì tốt biết mấy."], ["ex", "나는 내년에 <b>취직한다면</b> 좋겠어.", "Năm sau nếu tôi xin được việc làm thì tốt biết mấy."], ["p", "② <b>Mong muốn đối với người khác:</b> Bất kể khả năng thực hiện thế nào, người ta vẫn thường dùng '-다면 좋겠다'. Lý do là vì '-다면 좋겠다' mang lại cảm giác mềm mỏng, không gây áp lực cho người nghe hơn là '-(으)면 좋겠다'."], ["ex", "자주 연락해 <b>주신다면</b> 좋겠습니다.", "Nếu quý vị thường xuyên liên lạc cho thì thật tốt ạ."], ["ex", "음식을 남기지 않고 다 <b>드신다면</b> 좋겠어요.", "Nếu mọi người ăn hết mà không để thừa thức ăn thì tốt biết mấy."], ["ex", "친구와 사이좋게 <b>지낸다면</b> 좋겠어요.", "Nếu con hòa thuận với bạn bè thì tốt biết mấy."]], "practice": [{"vn": "Nếu có nhiều tiền thì tôi muốn đi du lịch vòng quanh thế giới.", "hint": "돈/많다/세계/여행/하다/싶다", "answer": "돈이 많다면 세계 여행을 하고 싶어요."}, {"vn": "Nếu có thể quay ngược thời gian thì tôi muốn làm học sinh lần nữa.", "hint": "시간/되돌리다/다시/학생/되다", "answer": "시간을 되돌릴 수 있다면 다시 학생이 되고 싶어요."}, {"vn": "Nếu ngày mai trời mưa thì hãy hủy chuyến leo núi.", "hint": "내일/비/오다/등산/취소하다", "answer": "내일 비가 온다면 등산은 취소합시다."}]}, {"num": 26, "term": "-다시피", "meaning": "Như đã..., đúng như (nhấn mạnh sự việc đúng như đã biết/thấy)", "blocks": [["p", "Mang nghĩa 'gần như giống với hành động ở phía trước' hoặc dùng để xác nhận lại."], ["p", "<b>1. Dùng với nghĩa 'gần như giống với hành động ở phía trước'</b>"], ["ex", "우리는 <b>싸우다시피</b> 회의를 했다.", "Chúng tôi đã họp mà gần như là cãi nhau."], ["ex", "사업 실패로 수연이의 집은 거의 <b>망하다시피</b> 하였다.", "Vì thất bại trong kinh doanh nên nhà Su-yeon gần như là phá sản."], ["p", "<b>2. Dùng làm trạng từ xác nhận lại một thực tế mà người nghe vốn đã biết</b>"], ["ex", "<b>보다시피</b>, 요즘은 신문 볼 틈도 없다.", "Như bạn thấy đấy, dạo này đến thời gian xem báo cũng không có."], ["ex", "이미 <b>아시다시피</b>, 지금은 중소기업의 사정이 좋지 않습니다.", "Như quý vị đã biết rồi đấy, hiện tại tình hình của các doanh nghiệp vừa và nhỏ không được tốt."]], "practice": [{"vn": "Như các bạn cũng đã biết, vấn đề này rất nghiêm trọng.", "hint": "여러분/알다/문제/매우/심각하다", "answer": "여러분도 아다시피 이 문제는 매우 심각합니다."}, {"vn": "Như các bạn thấy đấy, hôm nay thời tiết rất đẹp.", "hint": "보다/오늘/날씨/아주/좋다", "answer": "보다시피 오늘 날씨가 아주 좋습니다."}, {"vn": "Như mọi người đều biết, anh ấy là người rất chăm chỉ.", "hint": "다들/알다/사람/매우/성실하다", "answer": "다들 알다시피 그는 매우 성실한 사람입니다."}]}, {"num": 27, "term": "-더니(마는/만)", "meaning": "Đã... (rồi) mà, vậy mà (kể lại điều đã quan sát/trải qua ở quá khứ rồi dẫn đến kết quả bất ngờ)", "blocks": [["p", "Dùng khi so sánh quá khứ và hiện tại, hoặc nói về kết quả xảy ra do sự việc trong quá khứ. Mệnh đề trước phải viết về thực tế mà người nói <b>trực tiếp nhìn thấy</b>. Chủ ngữ của mệnh đề trước và sau thường giống nhau. Thường thì chủ ngữ của mệnh đề trước là 'người khác'. Không thể đổi '-더니' thành '-았/었더니'."], ["p", "<b>1. So sánh sự thay đổi giữa quá khứ và hiện tại: Có thể thay bằng '-는데'.</b>"], ["ex", "시험 기간에는 도서관에 사람이 <b>많더니</b> 시험이 끝나니까 적어졌어요.", "Trong kỳ thi thì thư viện đông người, nhưng thi xong cái là thưa thớt hẳn."], ["ex", "처음에는 김치가 <b>맵더니</b> 지금은 안 매워요.", "Bắt đầu thì kim chi cay, nhưng giờ thì không cay nữa."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더니' và '-는데'</b>", "<b>1. -더니:</b> Dùng khi hồi tưởng lại việc bản thân trực tiếp nhìn", "thấy."]], ["ex", "어제는 길이 <b>복잡하더니</b> 오늘은 그렇지 않아요.", "Hồi tưởng lại tình trạng tắc đường hôm qua để so sánh với hôm nay."], ["bq", ["<b>2. -는데:</b> Dùng khi hồi tưởng lại thực tế mà bản thân biết (dù", "không trực tiếp nhìn thấy)."]], ["ex", "어제는 길이 <b>복잡했는데</b> 오늘은 그렇지 않아요.", "Đơn thuần so sánh thực tế hôm qua tắc đường với hôm nay."], ["p", "+--------+-----------------+------------------+------------------------+ | >      | > <b>Mệnh đề     | > </b>Mệnh đề      | > <b>Người nói trực     | |  </b>Cấu | > trước<b>       | > sau</b>          | > tiếp nhìn thấy/cảm   | | >      |                 |                  | > nhận<b>               | | trúc</b> |                 |                  |                        | +========+=================+==================+========================+ | > <b>-  | > Quá khứ       | > Việc xảy ra    | > $bigcirc$        | | 더니</b> |                 | > sau mệnh đề    |                        | |        |                 | > trước          |                        | +--------+-----------------+------------------+------------------------+ | > <b>-  | > Quá khứ, Hiện | > Quá khứ, Hiện  | > Không liên quan      | | 는데</b> | > tại, Tương    | > tại, Tương lai |                        | |        | > lai           |                  |                        | +--------+-----------------+------------------+------------------------+"], ["p", "<b>2. Kết quả xuất hiện do sự việc trong quá khứ: Có thể thay bằng '-아/어서'.</b>"], ["ex", "친구가 시험공부를 열심히 <b>하더니</b> 시험에서 1등을 했어요.", "Bạn tôi học ôn thi chăm chỉ nên đã đứng nhất trong kỳ thi."], ["ex", "어릴 때부터 노래를 <b>좋아하더니</b> 가수가 됐어요.", "Từ nhỏ đã thích hát ca nên lớn lên đã trở thành ca sĩ."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더니' và '-아/어서'</b>", "<b>1. -더니:</b> Chủ yếu nhấn mạnh mệnh đề sau."]], ["ex", "어릴 때부터 노래를 <b>좋아하더니</b> 가수가 됐어요.", "Nhấn mạnh việc bây giờ đã trở thành ca sĩ. Mang ý nghĩa người nói đã trực tiếp nhìn thấy hình ảnh thích hát từ nhỏ."], ["bq", ["<b>2. -아/어서:</b> Chủ yếu nhấn mạnh mệnh đề trước."]], ["ex", "어릴 때 노래를 <b>좋아서</b> 가수가 됐어요.", "Lý do trở thành ca sĩ là vì hồi nhỏ thích hát. Ngay cả khi không trực tiếp thấy hình ảnh hồi nhỏ vẫn có thể nói câu này."], ["p", "+--------------+--------------------+----------------------------------+ | > <b>Cấu      | > </b>Cái được nhấn  | > <b>Người nói trực tiếp nhìn     | | > trúc</b>     | > mạnh<b>           | > thấy/cảm nhận</b>                | +==============+====================+==================================+ | > <b>-더니    | > Mệnh đề sau (Kết | > $bigcirc$                  | | > (Kết       | > quả)             |                                  | | > quả)</b>     |                    |                                  | +--------------+--------------------+----------------------------------+ | > <b>-아/어서 | > Mệnh đề trước    | > Không liên quan                | | > (Lý do)</b>  | > (Lý do)          |                                  | +--------------+--------------------+----------------------------------+"]], "practice": [{"vn": "Hôm qua trời trong xanh vậy mà hôm nay lại mưa.", "hint": "어제/날씨/맑다/오늘/비/오다", "answer": "어제는 날씨가 맑더니 오늘은 비가 오네요."}, {"vn": "Em tôi cứ khóc mãi vậy mà bỗng nhiên im lặng.", "hint": "동생/계속/울다/갑자기/조용해지다", "answer": "동생이 계속 울더니 갑자기 조용해졌다."}, {"vn": "Anh ấy đã trăn trở một hồi lâu rồi cuối cùng từ bỏ.", "hint": "한참/고민하다/결국/포기하다", "answer": "그는 한참 고민하더니 결국 포기했다."}]}, {"num": 28, "term": "-더라도", "meaning": "Dù có... đi nữa thì (nhượng bộ mạnh, giả định)", "blocks": [["p", "Mặc dù giả định như mệnh đề trước, nhưng ở mệnh đề sau lại xuất hiện sự trái ngược với giả định của mệnh đề trước."], ["ex", "화가 <b>나더라도</b> 참으세요.", "Dù có nổi giận thì cũng hãy nhẫn nại."], ["ex", "문제가 <b>쉽더라도</b> 잘 생각해서 대답하십시오.", "Dù câu hỏi có dễ thì cũng hãy suy nghĩ kỹ rồi mới trả lời."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-더라도' và '-아/어/여도'</b>", "'-더라도' có khả năng thực hiện tương đối thấp hơn so với", "'-아/어/여도'."]], ["ex", "얘기하기 <b>싫더라도 / 싫어도</b> 하세요.", "Dù không thích nói chuyện thì cũng hãy nói đi."], ["ex", "수연이를 <b>만나더라도 / 만나도</b> 얘기는 안 할 거예요.", "Dù có gặp Su-yeon thì tôi cũng sẽ không nói chuyện đâu."], ["ex", "이민을 <b>가더라도 / 가도</b> 김치는 먹을 거예요.", "Dù có đi nhập cư thì tôi vẫn sẽ ăn kim chi."]], "practice": [{"vn": "Dù có bận đến mấy thì cũng phải ăn cơm chứ.", "hint": "아무리/바쁘다/밥/먹다", "answer": "아무리 바쁘더라도 밥은 먹고 다녀야지요."}, {"vn": "Dù trời có mưa đi nữa thì chúng tôi vẫn sẽ xuất phát theo kế hoạch.", "hint": "비/오다/예정대로/출발하다", "answer": "비가 오더라도 우리는 예정대로 출발할 거예요."}, {"vn": "Dù có thất bại đi nữa thì tôi sẽ thử thách lại lần nữa.", "hint": "실패하다/다시/도전하다", "answer": "실패하더라도 다시 도전할 거예요."}]}, {"num": 29, "term": "-도록", "meaning": "Để, sao cho (đến mức/mục tiêu nào đó, thường dùng với động từ chỉ nỗ lực)", "blocks": [["p", "<b>1. Nói một cách nói khéo léo, nhẹ nhàng. Không nói mang tính khẳng định tuyệt đối. Đứng sau động từ. Nhấn mạnh ý chí của người nói.</b>"], ["ex", "조용히 <b>하도록</b> 하세요. (조용히 하세요.)", "Hãy giữ trật tự nhé. / Hãy giữ trật tự."], ["ex", "수업 시간에 늦지 <b>않도록</b> 하십시오. (수업에 늦지 마십시오.)", "Xin đừng đến muộn giờ học nhé. / Đừng đến muộn giờ học."], ["ex", "앞으로 매일 운동<b>하도록</b> 할 거예요. (앞으로 매일 운동할 거예요.)", "Sau này tôi sẽ tập thể dục mỗi ngày. / Sau này tôi sẽ tập thể dục mỗi ngày."], ["ex", "자주 <b>만나도록</b> 하자. (자주 만나자.)", "Chúng mình hãy thường xuyên gặp nhau nhé. / Thường xuyên gặp nhau nào."], ["p", "<b>2. Thời gian, Mức độ: Dùng với nghĩa 'cho đến khi -(으)ㄹ', 'đến mức -(으)ㄹ'.</b>"], ["ex", "10시가 <b>되도록</b> 학생들이 학교에 오지 않았습니다. (10시가 될 때까지)", "Cho đến tận 10 giờ mà học sinh vẫn chưa đến trường."], ["ex", "시험 전날에 밤새<b>도록</b> 공부했습니다. (밤이 샐 때까지)", "Tôi đã học suốt đêm cho đến sáng vào ngày trước kỳ thi."], ["ex", "집을 떠난 지 3년이 <b>지나도록</b> 소식이 없어서 부모님이 걱정하셨어요. (지날 때까지)", "Rời nhà đã hơn 3 năm mà không có tin tức gì nên bố mẹ rất lo lắng."], ["p", "<b>3. -게: Thể hiện sự sai khiến (bắt người khác làm như vậy), Phó từ (bổ nghĩa cho động từ phía sau)</b>"], ["p", "① <b>Biểu hiện sai khiến:</b> Thể hiện tình huống chủ ngữ làm cho đối tượng khác thực hiện một hành động nào đó. Mọi '-도록' đều có thể đổi thành '-게'."], ["ex", "부모님은 내가 한국에서 공부<b>하도록</b> 허락하셨어요. $rightarrow$ 부모님은 내가 한국에서 공부<b>하게</b> 허락하셨어요.", "Bố mẹ đã cho phép tôi học tập tại Hàn Quốc."], ["ex", "엄마가 나에게 슈퍼에서 우유를 사 <b>오도록</b> 하셨어요. $rightarrow$ 엄마가 나에게 슈퍼에서 우유를 사 <b>오게</b> 하셨어요.", "Mẹ đã bảo tôi đi siêu thị mua sữa về."], ["p", "② <b>Biểu hiện phó từ:</b> Giải thích cụ thể cho động từ đứng trước động từ. Mọi '-도록' đều có thể đổi thành '-게'."], ["ex", "실수하지 <b>않도록</b> 조심하세요. $rightarrow$ 실수하지 <b>않게</b> 조심하세요.", "Hãy cẩn thận để không mắc sai lầm."], ["ex", "약속을 잊어버리지 <b>않도록</b> 공책에 적습니다. $rightarrow$ 약속을 잊어버리지 <b>않게</b> 공책에 적습니다.", "Tôi ghi vào sổ tay để không quên cuộc hẹn."]], "practice": [{"vn": "Tôi sẽ nỗ lực để mọi người có thể sống thoải mái.", "hint": "모두/편하다/지내다/노력하다", "answer": "모두가 편하게 지낼 수 있도록 노력하겠습니다."}, {"vn": "Hãy mặc ấm để không bị cảm.", "hint": "감기/걸리다/따뜻하다/입다", "answer": "감기에 걸리지 않도록 따뜻하게 입으세요."}, {"vn": "Hãy nhanh lên để không bị trễ.", "hint": "늦다/서두르다", "answer": "늦지 않도록 서두릅시다."}]}, {"num": 30, "term": "-든지", "meaning": "Dù là... đi nữa, bất kể (liệt kê các lựa chọn, không quan trọng cái nào)", "blocks": [["p", "<b>1. Khi '-든지' được dùng với nghĩa 'không liên quan dù thế nào đi nữa', nó bất luận được dùng đơn lẻ hay lặp lại, đều có thể thêm '간에' vào phía sau để nhấn mạnh thêm ý nghĩa của từ đó.</b>"], ["ex", "<b>뛰어가든지 걸어가든지</b> 간에 늦지는 않는다.", "Dù chạy đi hay đi bộ đi thì cũng không bị trễ đâu."], ["ex", "수연이가 <b>좋아하든지 싫어하든지</b> 간에 선물을 주었다.", "Dù Su-yeon thích hay ghét thì tôi vẫn tặng quà."], ["p", "<b>2. Khi '-든지' được dùng với nghĩa chọn một trong nhiều cái được liệt kê ra thì cũng không sao, thường hai từ đi kèm sẽ mang ý nghĩa trái ngược nhau.</b>"], ["ex", "<b>가든지 오든지</b> 네가 하고 싶은 대로 해라.", "Đi hay đến thì tùy bạn làm theo ý mình muốn."], ["ex", "선물이 <b>많든지 적든지</b> 고마울 뿐이다.", "Quà nhiều hay ít thì tôi cũng đều biết ơn cả."], ["p", "<b>3. '-든지' còn kết hợp với vĩ tố kết thúc câu '다, 라, 자'. Trường hợp này là dạng rút gọn của '...고(라, 자) 하다' + '-든지'.</b>"], ["ex", "오늘 오라고 <b>하든지</b> 내일 오라고 <b>하든지</b> 무슨 얘기가 있을 거야. $rightarrow$ 오늘 <b>오라든지</b> 내일 <b>오라든지</b> 무슨 얘기가 있을 거야.", "Bảo hôm nay đến hay bảo ngày mai đến thì chắc cũng sẽ có chuyện gì đó thôi."]], "practice": [{"vn": "Dù mưa hay tuyết thì trận đấu vẫn diễn ra theo kế hoạch.", "hint": "비/오다/눈/오다/경기/예정대로/진행되다", "answer": "비가 오든지 눈이 오든지 경기는 예정대로 진행됩니다."}, {"vn": "Dù em làm gì đi nữa thì anh cũng sẽ ủng hộ.", "hint": "무엇/하다/응원하다", "answer": "네가 무엇을 하든지 나는 응원할게."}, {"vn": "Uống cà phê hay uống trà cũng được, cứ tùy ý bạn.", "hint": "커피/마시다/차/마시다/편하다/하다", "answer": "커피를 마시든지 차를 마시든지 편한 대로 하세요."}]}, {"num": 31, "term": "-듯(이)", "meaning": "Như, giống như (so sánh, minh họa cách thức)", "blocks": [["p", "<b>1. Thể hiện mệnh đề sau cũng như vậy giống như nội dung mà mệnh đề trước hàm ý. Mang nghĩa 'giống như việc...'.</b>"], ["ex", "사람마다 얼굴이 <b>다르듯</b> 나라마다 풍습도 다르다.", "Giống như khuôn mặt mỗi người mỗi khác, phong tục mỗi quốc gia cũng khác nhau."], ["ex", "앞에서도 얘기<b>했듯이</b> 광고는 하나의 예술이다.", "Giống như đã nói ở trước, quảng cáo là một nghệ thuật."], ["p", "<b>2. Dùng khi so sánh các thực tế tương tự nhau.</b>"], ["ex", "땀이 비 <b>오듯</b> 쏟아진다.", "Mồ hôi rơi xuống như mưa trút."], ["ex", "이 <b>잡듯</b> 뒤져도 반지를 찾을 수 없었다.", "Dù có lục tìm kỹ như bắt rận thì vẫn không thể tìm thấy chiếc nhẫn."]], "practice": [{"vn": "Đúng như tôi đã nghe đồn, anh ấy thật sự là người rất tốt bụng.", "hint": "소문/듣다/정말/친절하다/사람", "answer": "소문으로 들었듯이 그는 정말 친절한 사람이었다."}, {"vn": "Đúng như đã dự đoán, đề thi rất khó.", "hint": "예상하다/시험/문제/어렵다", "answer": "예상했듯이 시험 문제가 어려웠다."}, {"vn": "Hãy nói chuyện tự nhiên như dòng nước chảy.", "hint": "물/흐르다/자연스럽다/이야기하다", "answer": "물 흐르듯이 자연스럽게 이야기하세요."}]}, {"num": 32, "term": "-아/어/여 가지고", "meaning": "...rồi (hành động trước hoàn tất, giữ nguyên trạng thái đó để làm hành động sau — khẩu ngữ)", "blocks": [["p", "Thực hiện hành động ở mệnh đề trước, duy trì/nắm giữ kết quả đó rồi thực hiện hành động ở mệnh đề sau. Dùng nhiều trong văn nói (khẩu ngữ)."], ["p", "<b>1. Kết hợp với động từ hành động: Thực hiện hành động ở mệnh đề trước, sau đó dựa trên kết quả đó để hành động ở mệnh đề sau được diễn ra.</b>"], ["ex", "편지를 <b>써 가지고</b> 우체통에 넣었어요.", "Tôi viết thư xong rồi bỏ vào hòm thư."], ["ex", "음식을 너무 많이 <b>해 가지고</b> 남았어요.", "Làm quá nhiều đồ ăn nên đã bị thừa."], ["p", "<b>2. Kết hợp với tính từ/động từ trạng thái: Trạng thái ở mệnh đề trước thường gây ảnh hưởng đến mệnh đề sau nhiều hơn là mang nghĩa nắm giữ/duy trì.</b>"], ["ex", "사무실이 <b>추워 가지고</b> 아무 일도 못 했어요.", "Văn phòng lạnh quá nên tôi chẳng làm được việc gì cả."], ["ex", "선생님과 정이 <b>들어 가지고</b> 헤어지기 싫었습니다.", "Đã nảy sinh tình cảm với thầy/cô nên tôi không muốn chia tay."]], "practice": [{"vn": "Tôi đã gói ghém hành lý xong rồi xuất phát.", "hint": "짐/다/싸다/출발하다", "answer": "짐을 다 싸 가지고 출발했어요."}, {"vn": "Tôi đã dành dụm tiền rồi mua nhà.", "hint": "돈/모으다/집/사다", "answer": "돈을 모아 가지고 집을 샀어요."}, {"vn": "Tôi đã ăn cơm xong rồi đi học.", "hint": "밥/먹다/학교/가다", "answer": "밥을 먹어 가지고 학교에 갔어요."}]}, {"num": 33, "term": "-아/어/여다(가)", "meaning": "...rồi mang đi (hành động trước hoàn tất, mang kết quả đó đến nơi khác)", "blocks": [["p", "<b>1. Hành động ở mệnh đề trước được thực hiện tại một địa điểm nhất định, rồi mang kết quả thu được từ đó đến địa điểm thứ hai để thực hiện hành động ở mệnh đề sau. Có đặc trưng là 'sự di chuyển địa điểm'.</b>"], ["ex", "만두를 <b>사다가</b> 먹었어요.", "Tôi mua bánh xếp về rồi ăn."], ["ex", "숙제를 <b>해다가</b> 선생님께 드렸어요.", "Tôi làm bài tập về nhà rồi nộp cho giáo viên."], ["p", "<b>2. Nhìn thì có vẻ giống với '-아/어서' vốn chỉ thứ tự, nhưng trường hợp của '-아/어/여다(가)' thì địa điểm xảy ra ở mệnh đề trước và mệnh đề sau phải khác nhau, còn '-아/어서' thì không bị giới hạn bởi địa điểm xảy ra hành động.</b>"], ["bq", ["<b>Tìm hiểu thêm | So sánh '-아/어/여다가' và '-아/어/여 가지고'</b>", "'-아/어/여다가' thể hiện hành động ở mệnh đề trước và mệnh đề sau được", "thực hiện ở hai nơi khác nhau, còn '-아/어/여 가지고' thì không có ý", "nghĩa chuyển đổi địa điểm."]]], "practice": [{"vn": "Tôi đã làm đồ ăn rồi mang đến nhà bạn.", "hint": "음식/만들다/친구/집/가져가다", "answer": "음식을 만들어다가 친구 집에 가져갔어요."}, {"vn": "Tôi đã mượn sách rồi mang cho em.", "hint": "책/빌리다/동생/주다", "answer": "책을 빌려다가 동생에게 줬어요."}, {"vn": "Tôi đã mua hoa rồi mang tặng mẹ.", "hint": "꽃/사다/어머니/드리다", "answer": "꽃을 사다가 어머니께 드렸어요."}]}, {"num": 34, "term": "-아/어/여서 그런지", "meaning": "Có lẽ vì... nên (phỏng đoán lý do)", "blocks": [["p", "Mang nghĩa 'không thể khẳng định chắc chắn là do mệnh đề trước nên mới dẫn đến kết quả ở mệnh đề sau, nhưng có vẻ là vậy'."], ["ex", "밥을 <b>먹어서 그런지</b> 잠이 와요.", "Không biết có phải do ăn cơm xong không mà tôi thấy buồn ngủ."], ["ex", "30분이나 <b>기다려서 그런지</b> 승현이는 약간 화가 나 있었다.", "Không biết có phải vì đã chờ suốt 30 phút không mà Seung-hyun có chút giận dữ."], ["bq", ["<b>Tìm hiểu thêm | '-(이)라서 그런지'</b>", "Khi gắn vào '이다' (là) thì dùng dưới dạng <b>'-(이)라서 그런지'</b>."]], ["ex", "너는 <b>교포라서 그런지</b> 한국말을 쉽게 배우는구나.", "Không biết có phải vì cậu là kiều bào không mà học tiếng Hàn dễ dàng thật đấy."], ["ex", "유명한 배우가 출연하는 <b>영화라서 그런지</b> 극장에 사람이 많다.", "Không biết có phải vì là bộ phim có diễn viên nổi tiếng đóng không mà rạp chiếu phim đông người thế."]], "practice": [{"vn": "Có lẽ vì trời lạnh nên trên đường không có người.", "hint": "날씨/춥다/거리/사람/없다", "answer": "날씨가 추워서 그런지 거리에 사람이 없다."}, {"vn": "Có lẽ vì không ngủ được nên cứ buồn ngủ suốt.", "hint": "잠/못 자다/계속/졸리다", "answer": "잠을 못 자서 그런지 계속 졸리다."}, {"vn": "Có lẽ vì công việc nhiều nên dạo này trông bạn mệt mỏi.", "hint": "일/많다/요즘/피곤하다/보이다", "answer": "일이 많아서 그런지 요즘 피곤해 보여요."}]}, {"num": 35, "term": "-아/어/여야(만)", "meaning": "Phải... mới (điều kiện bắt buộc, nhấn mạnh)", "blocks": [["p", "Không dùng trong câu mệnh lệnh và rủ rê. Thường dùng để biểu thị nguyên tắc hoặc chân lý."], ["p", "<b>1. Thể hiện tính bắt buộc hoặc điều kiện tất yếu tối thiểu của mệnh đề trước.</b>"], ["ex", "한국말을 <b>알아야</b> 한국에서 살기가 편하지요.", "Phải biết tiếng Hàn thì sống ở Hàn Quốc mới thuận tiện chứ."], ["ex", "택시를 <b>타야</b> 학교에 늦지 않습니다.", "Phải đi xe taxi thì mới không bị trễ học."], ["p", "<b>2. Cũng có thể dùng trong trường hợp lấy thực tế trái ngược làm điều kiện tùy theo mệnh đề sau. Lúc này có thể dùng kết hợp với vĩ tố thì '-았/었/였-'.</b>"], ["ex", "비가 안 <b>왔어야</b> 소풍을 갔을 텐데요.", "Phải chi trời không mưa thì đã đi dã ngoại rồi."], ["ex", "컴퓨터를 잘 <b>해야</b> 취직을 할 텐데.", "Phải giỏi máy tính thì mới xin được việc chứ."], ["p", "<b>3. '-아/어/여야' kết hợp với vĩ tố kết thúc câu '-지' hoặc tiểu từ '만' có nghĩa là 'duy nhất' để thể hiện sự nhấn mạnh mạnh mẽ hơn.</b>"], ["ex", "말하기 연습을 <b>해야지</b> 발음을 고칠 수 있어요.", "Phải luyện nói thì mới sửa được phát âm."], ["ex", "자주 <b>만나야만</b> 정이 들어요.", "Phải thường xuyên gặp nhau thì mới nảy sinh tình cảm."], ["p", "<b>4. Giả định rằng mình đưa ra tính bắt buộc tất yếu nhưng cũng chẳng có tác dụng gì. Mang nghĩa tương tự '-어/아/여도', '-어/아/여 봤자'.</b>"], ["ex", "아무리 <b>졸라야</b> 아버지는 꺼떡도 안 하신다.", "Dù cho có nằmnheo thế nào thì bố cũng chẳng nhúc nhích."], ["ex", "정직하게 <b>살아야</b> 알아주는 사람은 아무도 없을 것이다.", "Dù có sống trung thực thì cũng chẳng có ai công nhận đâu."], ["p", "<b>5. Khi gắn thì vào thành dạng '-았/었/였어야' thì nó thể hiện sự hối hận về một trường hợp cụ thể chứ không phải chân lý thông thường.</b>"], ["ex", "정기 검진을 <b>받았어야</b> 초기에 병을 발견했을 텐데요.", "Giá mà đã đi khám sức khỏe định kỳ thì đã phát hiện ra bệnh từ giai đoạn đầu rồi."], ["ex", "미리 약속을 <b>했어야</b> 오늘 만날 수 있었을 것이다.", "Giá mà đã hẹn trước từ sớm thì hôm nay đã có thể gặp nhau rồi."]], "practice": [{"vn": "Phải nỗ lực chăm chỉ thì mới có thể thành công.", "hint": "열심히/노력하다/성공하다", "answer": "열심히 노력해야 성공할 수 있어요."}, {"vn": "Phải xây dựng nền tảng tốt thì thực lực mới tiến bộ.", "hint": "기초/잘/다지다/실력/늘다", "answer": "기초를 잘 다져야 실력이 늘어요."}, {"vn": "Phải đích thân đến xem thì mới biết được bộ mặt thật.", "hint": "직접/가 보다/진짜/모습/알다", "answer": "직접 가 봐야 진짜 모습을 알 수 있어요."}]}, {"num": 36, "term": "-았/었/였더니", "meaning": "Đã... thì ra, hóa ra (kể lại phát hiện bất ngờ sau khi thực hiện hành động ở quá khứ)", "blocks": [["p", "Dùng khi người nói hồi tưởng lại hành động mà chính mình đã làm trong quá khứ."], ["ex", "약을 <b>먹었더니</b> 다 나았어요.", "Tôi uống thuốc vào cái là khỏi hẳn luôn."], ["ex", "생일 축하 카드를 <b>보냈더니</b> 고맙다는 전화가 왔어요.", "Tôi gửi thiệp chúc mừng sinh nhật thì nhận được điện thoại cảm ơn."], ["bq", ["<b>Tìm hiểu thêm | Chủ ngữ ngôi thứ 3 và '-았/었/였더니'</b>", "Khi chủ ngữ của mệnh đề trước là ngôi thứ 3, người nói quan sát thấy", "hành động của người đó đã hoàn thành và nói về kinh nghiệm đó."]], ["ex", "그녀가 질문을 <b>했더니</b> 선생님은 자세히 설명하셨다.", "Khi cô ấy đặt câu hỏi, giáo viên đã giải thích rất chi tiết."], ["ex", "그가 춤을 <b>췄더니</b> 모두 박수를 쳤습니다.", "Khi anh ấy nhảy, tất cả mọi người đều vỗ tay."]], "practice": [{"vn": "Tôi mở cửa sổ ra thì hóa ra bên ngoài đang có tuyết rơi.", "hint": "창문/열다/밖/눈/오다", "answer": "창문을 열었더니 밖에 눈이 오고 있었다."}, {"vn": "Tôi uống thuốc thì hóa ra khỏi bệnh ngay.", "hint": "약/먹다/금방/낫다", "answer": "약을 먹었더니 금방 나았다."}, {"vn": "Tôi đã tập thể dục chăm chỉ thì hóa ra giảm được nhiều cân.", "hint": "열심히/운동하다/살/많이/빠지다", "answer": "열심히 운동했더니 살이 많이 빠졌다."}]}, {"num": 37, "term": "-았/었/였더라면", "meaning": "Nếu như đã... thì (giả định trái với quá khứ, tiếc nuối)", "blocks": [["p", "Về mặt nội dung câu, có 2 trường hợp: Hồi tưởng lại sự việc đã hoàn thành trong quá khứ rồi hối hận, hoặc cảm thấy may mắn."], ["p", "<b>1. Trường hợp cảm thấy hối hận vì đã làm (hoặc không làm) như vậy trong quá khứ: Là lời hối hận rằng nếu không hành động như vậy thì đã có kết quả tốt hơn. Mệnh đề sau thường dùng các dạng như '-(으)ㄹ 것이다', '-(으)ㄹ 걸', '-(으)ㄹ 텐데'. Cụm '-(으)ㄹ 걸 그랬다' biểu thị sự lặp lại của lời nói phía trước với nghĩa là 'nếu... thì đã... rồi'.</b>"], ["ex", "일찍 <b>떠났더라면</b> 어둡기 전에 도착할 텐데.", "Giá mà xuất phát sớm hơn thì đã đến nơi trước khi trời tối rồi."], ["ex", "아파도 <b>참았더라면</b> 좋았을 걸 그랬어요.", "Dù đau nhưng giá mà cố chịu đựng thì đã tốt biết mấy."], ["p", "<b>2. Trường hợp cảm thấy may mắn vì đã làm như vậy trong quá khứ:</b> Là lời nói nghĩ về trường hợp nếu không làm như vậy thì đã gặp chuyện không hay, cho thấy hành động trong quá khứ là việc làm đúng đắn. Mệnh đề sau thường dùng các dạng như '-(으)ㄹ 것이다', '-(으)ㄹ 뻔했다'."], ["ex", "수영을 안 <b>했더라면</b> 굉장히 뚱뚱했을 거예요.", "Nếu hồi đó không tập bơi thì chắc bây giờ tôi đã rất béo rồi."], ["ex", "누리가 도와주지 <b>않았더라면</b> 고생할 뻔했다.", "Nếu Nuri không giúp đỡ thì tôi đã vất vả rồi."]], "practice": [{"vn": "Nếu như đã cố gắng thêm một chút thì có lẽ đã đậu rồi.", "hint": "조금/더/노력하다/합격하다", "answer": "조금만 더 노력했더라면 합격했을 텐데."}, {"vn": "Nếu như lúc đó không gặp người đó thì có lẽ giờ tôi đang sống một cuộc đời khác.", "hint": "그때/사람/만나다/지금/다르다/삶/살다", "answer": "그때 그 사람을 만나지 않았더라면 지금과 다른 삶을 살고 있을 거예요."}, {"vn": "Nếu như đã biết trước thì có lẽ tôi đã chuẩn bị rồi.", "hint": "미리/알다/준비하다", "answer": "미리 알았더라면 준비를 했을 텐데요."}]}, {"num": 38, "term": "-았/었/였던들", "meaning": "Nếu như đã... thì (giả định trái với quá khứ, mang tính văn chương/trang trọng hơn '-더라면')", "blocks": [["p", "Thể hiện sự hối hận về một hành động hoặc trạng thái trong quá khứ. Mệnh đề sau sẽ viết về sự thật trái ngược với thực tế hoặc sự thật không thể xảy ra trên thực tế."], ["ex", "미리 미리 발표 준비를 <b>했던들</b> 이렇게 밤을 새우지 않았을 텐데.", "Giá mà chuẩn bị bài phát biểu từ trước thì đã không phải thức đêm thế này."], ["ex", "점수가 1점만 더 <b>높았던들</b> 떨어지지는 않았을 텐데.", "Giá mà điểm số cao hơn chỉ 1 điểm thôi thì đã không bị trượt rồi."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-았/었/였던들' và '-았/었/였더라면'</b>", "<b>1. -았/었/였던들:</b> Chỉ dùng trong trường hợp nghĩ về sự việc với sự", "hối hận."]], ["ex", "조금만 더 건강에 신경을 <b>썼던들</b> 이만한 일에 쓰러지지는 않았을 텐데.", "Giá mà chú ý đến sức khỏe hơn một chút thì đã không bị gục ngã vì việc chừng này.) *→ Hối hận vì đã không chăm sóc sức khỏe."], ["bq", ["<b>2. -았/었/였더라면:</b> Dùng cho cả trường hợp hối hận về sự việc", "trong quá khứ lẫn trường hợp cảm thấy may mắn."]], ["ex", "네 말을 <b>들었더라면</b> 좋았을 텐데.", "Giá mà nghe lời cậu thì đã tốt rồi.) *→ Đang hối hận vì đã không nghe lời."], ["ex", "조금만 늦게 <b>도착했더라면</b> 기차를 못 탔을 것이다.", "Nếu đến muộn chỉ một chút thôi thì đã không đi kịp chuyến tàu rồi.) *→ Cảm thấy may mắn vì đã đến nơi không bị trễ nên đã đi được tàu."]], "practice": [{"vn": "Nếu như anh ấy đã cẩn thận thêm một chút thì tai nạn đã không xảy ra.", "hint": "조금/더/조심하다/사고/나다", "answer": "그가 조금만 더 조심했던들 사고가 나지 않았을 것이다."}, {"vn": "Nếu như đã đi bệnh viện sớm hơn thì có lẽ đã không nặng thế này.", "hint": "진작/병원/가다/심해지다", "answer": "진작 병원에 갔던들 이렇게 심해지지 않았을 텐데."}, {"vn": "Nếu như lúc đó đã từ bỏ thì đã không có thành công như hôm nay.", "hint": "그때/포기하다/지금/성공/없다", "answer": "그때 포기했던들 지금의 성공은 없었을 것이다."}]}, {"num": 39, "term": "-자", "meaning": "Vừa... thì (ngay sau khi, hành động sau nối tiếp lập tức)", "blocks": [["p", "<b>1. [Sau động từ] Thể hiện sau khi hành động ở mệnh đề trước kết thúc, hành động ở mệnh đề sau lập tức nối tiếp xảy ra.</b>"], ["ex", "문을 <b>열자</b> 새로운 세상이 펼쳐졌다.", "Vừa mở cửa ra, một thế giới mới liền mở ra trước mắt."], ["ex", "한국에는 까마귀 <b>날자</b> 배 떨어진다는 속담이 있다.", "Ở Hàn Quốc có câu tục ngữ \"Thậm chí quạ vừa bay lên thì lê đã rơi\" - Ngẫu nhiên gặp xui xẻo)."], ["p", "<b>2. [Sau một số động từ] Thể hiện nội dung ở mệnh đề trước trở thành nguyên nhân hoặc động cơ cho mệnh đề sau.</b>"], ["ex", "그를 <b>보자</b> 내 심장이 터질 듯이 뛰기 시작했어요.", "Vừa nhìn thấy anh ấy, tim tôi đã bắt đầu đập liên hồi như muốn nổ tung."], ["ex", "차에서 연기가 <b>나자</b> 운전자는 즉시 차에서 튀어나왔다.", "Ngay khi khói bùng lên từ xe, người tài xế liền lập tức lao ra khỏi xe."], ["p", "<b>3. [Sau '이다'] Thể hiện một sự vật/người nào đó sở hữu từ hai tư cách hoặc đặc điểm trở lên.</b>"], ["ex", "준형이는 유명한 <b>배우이자</b> 가수이다.", "Jun-hyeong vừa là diễn viên nổi tiếng vừa là ca sĩ."], ["ex", "활발하고 당찬 것은 나의 <b>장점이자</b> 단점입니다.", "Năng nổ và mạnh mạn vừa là ưu điểm vừa là khuyết điểm của tôi."], ["p", "<b>4. Thể hiện rằng dù hành động hay trạng thái ở mệnh đề trước có diễn ra thì cũng vô ích. Chủ yếu dùng dưới dạng '-아/어 보았자'.</b>"], ["ex", "기다려 <b>봤자</b> 이미 떠난 버스가 돌아오지는 않을 겁니다.", "Dù có chờ đợi thì chuyến xe bus đã rời đi cũng sẽ không quay lại đâu."], ["ex", "아무리 애원해 <b>봤자</b> 지금은 이연이의 마음을 돌릴 수 없을 거야.", "Dù có van xin thế nào thì bây giờ cũng chẳng thể làm thay đổi lòng I-yeon đâu."], ["p", "<b>5. Dùng khi nói về nội dung ở mệnh đề sau dựa trên căn cứ là những gì đã nhìn thấy hoặc nghe thấy. Chủ yếu dùng dưới dạng '보자 하니(까)', '듣자 하니(까)'.</b>"], ["ex", "<b>보자 하니</b> 내일도 날씨가 안 좋을 것 같네요.", "Xem chừng thì có vẻ ngày mai thời tiết cũng không tốt đâu."], ["ex", "<b>듣자 하니</b> 그녀가 드디어 귀국을 한다던데요.", "Nghe nói thì nghe bảo cuối cùng cô ấy cũng về nước rồi đấy."], ["p", "<b>6. Dùng khi thể hiện một tình huống hoàn toàn không thể nhẫn nại thêm được nữa. Chủ yếu dùng dưới dạng '보자 보자 하니까', '듣자 듣자 하니까'.</b>"], ["ex", "<b>보자 보자 하니까</b> 내가 우수워 보이니?", "Nhẫn nhịn xem mãi nên nhòm tôi trông buồn cười lắm à/coi thường tôi đấy à?"], ["ex", "정말 <b>듣자 듣자 하니까</b> 말이 너무 심하신 것 아닌가요?", "Thực sự nhẫn nhịn nghe mãi rồi, không phải lời nói của anh quá đáng lắm rồi sao?"], ["p", "<b>7. [Sau động từ] Dùng khi thể hiện người nói mang một ý đồ, mục đích, hy vọng nào đó.</b>"], ["ex", "몸을 <b>씻자 하니</b> 하필 그때 물이 안 나오지 뭐예요.", "Vừa định tắm rửa thì đúng lúc đó lại bị mất nước chứ nị."], ["ex", "여름옷을 세탁소에 <b>맡기자 하니</b> 날씨가 다시 더워지네요.", "Vừa định mang quần áo mùa hè ra tiệm giặt ủi thì thời tiết lại nóng trở lại."], ["bq", ["<b>Tìm hiểu thêm | Vĩ tố kết thúc câu '-자'</b>", "'-자' còn là vĩ tố kết thúc câu dùng khi rủ rê hoặc yêu cầu đối phương", "cùng làm một việc gì đó."]], ["ex", "우리 주말에 수영하러 <b>가자</b>.", "Cuối tuần này chúng mình cùng đi bơi đi."], ["ex", "시간이 늦었는데 조용히 좀 <b>하자</b>.", "Muộn rồi, chúng mình giữ trật tự một chút đi."]], "practice": [{"vn": "Vừa về đến nhà thì trời bắt đầu đổ mưa.", "hint": "집/도착하다/비/쏟아지다/시작하다", "answer": "집에 도착하자 비가 쏟아지기 시작했다."}, {"vn": "Vừa nghe tin đó thì tôi đã rơi nước mắt.", "hint": "소식/듣다/눈물/나다", "answer": "그 소식을 듣자 눈물이 났다."}, {"vn": "Vừa mở cửa ra thì gió mát ùa vào.", "hint": "문/열다/시원하다/바람/들어오다", "answer": "문을 열자 시원한 바람이 들어왔다."}]}, {"num": 40, "term": "-자마자", "meaning": "Ngay khi vừa... (nhấn mạnh tính tức thời hơn '-자')", "blocks": [["p", "Ngay sau khi sự việc ở mệnh đề trước kết thúc thì sự việc ở mệnh đề sau lập tức xảy ra. Đây là biểu hiện mang tính văn nói (khẩu ngữ), và chủ ngữ ở mệnh đề trước có thể là '나' (tôi). Mệnh đề sau có thể đi kèm với tất cả các thì quá khứ, hiện tại, tương lai."], ["ex", "아침에 <b>일어나자마자</b> 물을 마셔요.", "Sáng ra ngay khi vừa thức dậy là tôi uống nước."], ["ex", "한국에 <b>오자마자</b> 한국어를 배우기 시작했어요.", "Ngay khi vừa đến Hàn Quốc, tôi đã bắt đầu học tiếng Hàn."], ["ex", "졸업<b>하자마자</b> 취직할 거예요.", "Ngay khi vừa tốt nghiệp là tôi sẽ xin việc làm ngay."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-자마자' và '-자'</b>", "Mọi '-자' đều có thể thay thế bằng '-자마자'. Tuy nhiên, có nhiều", "trường hợp '-자마자' không thể thay thế bằng '-자'."]], ["p", "-------------------------------------------------------------------------------- <b>Tiêu chí</b>  <b>Khẩu    </b>Ý nghĩa thời  <b>Ý nghĩa kết   </b>Sự việc   <b>Thì của ngữ / Văn gian (Xảy ra    quả (Sau khi sự thông       mệnh đề viết</b>    ngay sau khi    việc phát       thường<b>    sau</b> xong)<b>         sinh)</b> ------------- --------- --------------- --------------- ----------- ------------ <b>-자</b>       Khẩu ngữ  ◯               ⊙               ×           Quá khứ < Văn viết"], ["p", "<b>-자마자</b>   Khẩu ngữ  ⊙               ×               ◯           Quá khứ, > Văn                                                Hiện tại, viết                                                  Tương lai --------------------------------------------------------------------------------"]], "practice": [{"vn": "Ngay khi tiết học vừa kết thúc, học sinh đã chạy ùa ra ngoài.", "hint": "수업/끝나다/학생들/뛰어나가다", "answer": "수업이 끝나자마자 학생들이 뛰어나갔다."}, {"vn": "Ngay khi vừa mở mắt là tôi kiểm tra điện thoại trước tiên.", "hint": "눈/뜨다/핸드폰/확인하다", "answer": "눈을 뜨자마자 핸드폰부터 확인해요."}, {"vn": "Ngay khi về đến nhà thì hãy đi tắm rửa nhé.", "hint": "집/도착하다/씻다", "answer": "집에 도착하자마자 씻으세요."}]}, {"num": 41, "term": "-자면", "meaning": "Nếu định... thì (giả định về ý định, thường kèm theo điều kiện/lưu ý)", "blocks": [["p", "<b>1. Dùng khi giả định một ý đồ hay mục đích nào đó và diễn đạt rằng theo điều kiện đó thì sẽ thực hiện hành động khác hoặc ở trong một trạng thái khác.</b>"], ["ex", "학교에 <b>가자면</b> 차를 타야 한다.", "Nếu muốn đến trường thì phải đi xe."], ["ex", "시험에 <b>합격하자면</b> 열심히 공부할 수밖에 없다.", "Nếu muốn đỗ kỳ thi thì không còn cách nào khác là phải học tập chăm chỉ."], ["p", "<b>2. Dùng khi đưa ra một tình huống dự kiến và diễn đạt trạng thái theo điều kiện đó.</b>"], ["ex", "달이 <b>뜨자면</b> 얼마나 더 기다려야 할까요?", "Nếu muốn trăng mọc thì còn phải chờ bao lâu nữa đây?"], ["ex", "날이 <b>밝자면</b> 아직 멀었구나.", "Nếu muốn trời sáng thì vẫn còn lâu lắm đấy."], ["p", "<b>3. Không thể dùng chung với các biểu hiện phủ định như '못' hoặc '-지 못하다', '-지 말다'. Nếu muốn dùng biểu hiện phủ định thì phải dùng các dạng phủ định như '안' hoặc '-지 않다'.</b>"], ["ex", "공부를 안 <b>하자면</b> 책을 살 필요가 없다. (O)", "Nếu không muốn học thì không cần mua sách."], ["ex", "공부를 하지 <b>않자면</b> 책을 살 필요가 없다. (O)", "Nếu không muốn học thì không cần mua sách."], ["ex", "공부를 못 <b>하자면</b> 책을 살 필요가 없다. (X)", ""], ["bq", ["<b>Tìm hiểu thêm | So sánh '-자면' và '-(으)려면'</b>", "'-자면' có thể thay thế bằng '-(으)려면' mà không có sự khác biệt lớn", "về mặt ý nghĩa."]], ["ex", "시험에 <b>합격하자면</b> 더 열심히 공부해야 해요. → 시험에 <b>합격하려면</b> 더 열심히 공부해야 해요.", "Nếu muốn đỗ kỳ thi thì phải học tập chăm chỉ hơn."]], "practice": [{"vn": "Nếu định thành công thì không được từ bỏ.", "hint": "성공하다/포기하다", "answer": "성공하자면 포기하지 말아야 한다."}, {"vn": "Nếu định để dành tiền thì phải tiết kiệm.", "hint": "돈/모으다/절약하다", "answer": "돈을 모으자면 절약해야 해요."}, {"vn": "Nếu định giải thích chi tiết thì sẽ mất chút thời gian.", "hint": "자세히/설명하다/시간/걸리다", "answer": "자세히 설명하자면 시간이 좀 걸려요."}]}, {"num": 42, "term": "-(느/으)니만큼", "meaning": "Vì... nên càng, tương xứng với mức độ (thể hiện lý do/mức độ tương ứng)", "blocks": [["p", "<b>1. Thể hiện mệnh đề trước là căn cứ để đo lường/ước lượng mức độ nói ở mệnh đề sau. Giống với nghĩa 'chỉ căn cứ mức độ' của '-ㄴ 만큼' nên có thể thay đổi cho nhau.</b>"], ["ex", "바람이 불고 날씨가 <b>추우니만큼</b> 출발을 연기해 봅시다.", "Vì gió thổi và thời tiết lạnh như thế này, chúng ta hãy hoãn lại việc xuất phát xem sao."], ["ex", "이것은 <b>유물이니만큼</b> 제대로 보존을 해야 할 겁니다.", "Vì cái này là di vật nên chắc chắn phải bảo tồn một cách đàng hoàng."], ["p", "<b>2. Có trường hợp một số danh từ chỉ thời gian hoặc địa điểm được lặp lại dưới dạng '-이/가 -(이)니만큼'. Lúc này, mệnh đề trước thể hiện thời gian hoặc địa điểm đặc biệt mà người nói và người nghe đều hiểu rõ, và mệnh đề sau được thực hiện dựa trên căn cứ đó.</b>"], ["ex", "<b>시대가 시대니만큼</b> 말조심해요. (자유롭게 말할 수 없는, 언론의 자유가 없는 시대)", "Thời buổi này là thời buổi như thế nên hãy cẩn thận lời ăn tiếng nói. - Thời đại không thể tự do nói năng, không có tự do ngôn luận"], ["ex", "<b>때가 때니만큼</b> 한잔하고 싶은 생각이 나는데요. (저녁 퇴근 때)", "Thời điểm này là thời điểm như thế nên tôi lại thấy muốn làm một ly đấy. - Lúc tan làm buổi tối"], ["ex", "<b>나이가 나이니만큼</b> 인생에 대한 고민이 있겠지요. (젊은 시절)", "Lứa tuổi này là lứa tuổi như thế nên chắc là sẽ có những trăn trở về cuộc đời rồi. - Thời trẻ"]], "practice": [{"vn": "Vì càng lớn tuổi nên càng phải chú ý sức khỏe hơn.", "hint": "나이/들다/건강/신경/쓰다", "answer": "나이가 들니만큼 건강에 더 신경을 써야 한다."}, {"vn": "Vì đã nỗ lực chăm chỉ nên chắc sẽ có kết quả tốt.", "hint": "열심히/노력하다/좋다/결과/있다", "answer": "열심히 노력했으니만큼 좋은 결과가 있을 거예요."}, {"vn": "Vì giá đắt nên chất lượng chắc cũng tốt.", "hint": "값/비싸다/품질/좋다", "answer": "값이 비싸니만큼 품질도 좋겠지요."}]}, {"num": 43, "term": "-(으)ㄴ/는 데다가", "meaning": "Không những... mà còn thêm (bổ sung thêm một đặc điểm/tình huống nữa)", "blocks": [["p", "Thể hiện hành động hoặc trạng thái ở mệnh đề sau được bổ sung thêm vào hành động/trạng thái ở mệnh đề trước. Động từ ở mệnh đề trước và mệnh đề sau phải có cùng tính chất, mang tính thống nhất để có thể tổng kết thành một kết luận duy nhất nối bằng '그래서' (Vì vậy)."], ["ex", "수연이는 머리가 <b>좋은 데다가</b> 열심히 해요.", "Su-yeon không những thông minh mà còn chăm chỉ nữa."], ["ex", "정은이는 술을 <b>마시는 데다가</b> 담배도 피워요.", "Jeong-eun không những uống rượu mà còn hút cả thuốc lá nữa."]], "practice": [{"vn": "Đường đã tắc, lại còn thêm mưa nên tôi bị trễ.", "hint": "길/막히다/비/오다/늦다", "answer": "길이 막히는 데다가 비까지 와서 늦었어요."}, {"vn": "Quán đó đã ngon, lại còn rẻ nữa.", "hint": "식당/맛있다/값/싸다", "answer": "그 식당은 맛있는 데다가 값도 싸요."}, {"vn": "Đã bận, lại còn ốm nữa nên rất vất vả.", "hint": "바쁘다/몸/아프다/힘들다", "answer": "바쁜 데다가 몸까지 아파서 힘들었어요."}]}, {"num": 44, "term": "-(으)ㄴ 채(로)", "meaning": "Trong trạng thái... (giữ nguyên trạng thái đó mà làm việc khác)", "blocks": [["p", "Mang nghĩa 'giữ nguyên trạng thái vốn có mà không thay đổi'. Thể hiện hành động ở mệnh đề sau được thực hiện trong trạng thái đang làm hành động ở mệnh đề trước."], ["ex", "아기는 과자를 손에 <b>쥔 채</b> 잠이 들었다.", "Em bé đã ngủ thiếp đi trong khi tay vẫn đang cầm chặt chiếc bánh/kẹo."], ["ex", "문을 열어 <b>놓은 채로</b> 자더니 감기가 들었어요.", "Tôi ngủ trong khi vẫn mở cửa ra nên đã bị cảm lạnh rồi."]], "practice": [{"vn": "Tôi đã ngủ quên trong khi đèn vẫn đang bật.", "hint": "불/켜다/잠/들다", "answer": "불을 켠 채로 잠이 들었어요."}, {"vn": "Anh ấy đã vào phòng trong khi vẫn đang mang giày.", "hint": "신발/신다/방/들어오다", "answer": "신발을 신은 채로 방에 들어왔어요."}, {"vn": "Tôi đã ra ngoài trong khi cửa sổ vẫn đang mở.", "hint": "창문/열다/외출하다", "answer": "창문을 연 채로 외출했어요."}]}, {"num": 45, "term": "-(으)ㄴ/는 대로", "meaning": "Theo như, đúng như (làm đúng theo cách/nội dung đã nêu)", "blocks": [["p", "Gắn vào động từ thể hiện ý nghĩa 'theo đúng hình dáng/trạng thái ở mệnh đề trước' hoặc 'ngay tại thời điểm sự việc nào đó xảy ra'."], ["p", "<b>1. Dùng với nghĩa 'theo đúng hình dáng, trạng thái của động từ phía trước': Dùng chung cho cả động từ hành động và động từ trạng thái.</b>"], ["ex", "선생님이 <b>부르시는 대로</b> 썼습니다.", "Tôi đã viết theo đúng những gì thầy/cô đọc."], ["ex", "<b>생각한 대로</b> 말해 봐요.", "Hãy thử nói theo đúng những gì bạn nghĩ xem nào."], ["p", "<b>2. Dùng với nghĩa 'ngay lập tức tại thời điểm sự việc xảy ra': Chỉ dùng với động từ hành động và chỉ dùng dưới dạng '-는 대로'.</b>"], ["ex", "<b>도착하는 대로</b> 문자를 드리겠습니다.", "Ngay khi đến nơi tôi sẽ gửi tin nhắn cho bạn."], ["ex", "그 사람을 <b>만나는 대로</b> 이 말을 전하겠습니다.", "Ngay khi gặp người đó tôi sẽ chuyển lại lời này."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ/는 대로' và '-자마자'</b>", "<b>1. -(으)ㄴ/는 대로:</b> Thể hiện hành động ở mệnh đề trước xảy ra và", "trạng thái đó đang tiếp diễn thì hành động ở mệnh đề sau diễn ra."]], ["ex", "그날 네가 <b>본 대로</b> 자세히 말해 주렴.", "Hãy nói chi tiết đúng như những gì con đã thấy hôm đó nhé."], ["ex", "지금부터는 설명을 <b>들은 대로</b> 선생님을 따라해 보세요.", "Từ bây giờ, hãy thử làm theo giáo viên đúng như những gì đã nghe giải thích nhé."], ["bq", ["<b>2. -자마자:</b> Chỉ chỉ thời điểm khi hành động ở mệnh đề trước vừa", "xảy ra, và thường mang tính ngẫu nhiên."]], ["ex", "그것은 내가 가게에서 <b>보자마자</b> 바로 산 옷이다.", "Đó là bộ quần áo tôi vừa nhìn thấy ở cửa hàng là mua ngay lập tức."], ["ex", "나는 침대에 <b>눕자마자</b> 잠이 들었다.", "Tôi vừa nằm xuống giường là ngủ thiếp đi ngay."], ["p", "<b>3. Dùng trong biểu hiện mạnh mẽ với nghĩa 'đến mức giới hạn không thể làm gì hơn được nữa': Nhập lặp lại một số động từ hành động dưới dạng '-ㄹ 대로'.</b>"], ["ex", "이젠 나도 모르겠다. <b>될 대로</b> 되어라.", "Bây giờ tôi cũng chịu rồi. Ra sao thì ra / Đến đâu thì đến."], ["ex", "<b>노력할 대로</b> 했는데도 일은 안 되었다.", "Tôi đã cố gắng hết mức có thể rồi mà công việc vẫn không thành."]], "practice": [{"vn": "Hãy làm theo đúng như lời tôi nói.", "hint": "제/말하다/따라 하다", "answer": "제가 말하는 대로 따라 하세요."}, {"vn": "Mọi việc đã diễn ra đúng như kế hoạch.", "hint": "계획하다/진행되다", "answer": "계획한 대로 진행됐어요."}, {"vn": "Hãy vẽ tranh đúng như những gì bạn đã thấy.", "hint": "보다/그림/그리다", "answer": "본 대로 그림을 그려 보세요."}]}, {"num": 46, "term": "-(으)ㄴ/는 대신에", "meaning": "Thay vì (thay thế cho vế trước bằng vế sau)", "blocks": [["p", "Thể hiện việc thay thế hành động hay trạng thái của mệnh đề trước bằng cái của mệnh đề sau, hoặc thể hiện sự vật/hành động khác chiếm vị trí đó chứ không phải là thứ vốn dĩ đương nhiên phải có."], ["ex", "윤수는 피아노를 <b>치는 대신에</b> 노래를 했다.", "Yun-su đã hát thay vì chơi piano."], ["ex", "규민이는 부모님을 안 <b>모시는 대신에</b> 용돈을 많이 드린다고 했다.", "Gyu-min nói rằng thay vì không phụng dưỡng bố mẹ thì sẽ biếu nhiều tiền tiêu dùng."]], "practice": [{"vn": "Tôi đã ăn bánh mì thay vì ăn cơm.", "hint": "밥/먹다/빵/먹다", "answer": "밥을 먹는 대신에 빵을 먹었어요."}, {"vn": "Thay vì cho tiền thì hãy dành thời gian cho tôi.", "hint": "돈/주다/시간/내다", "answer": "돈을 주는 대신에 시간을 내 주세요."}, {"vn": "Tôi đã viết thư thay vì nói bằng lời.", "hint": "말/하다/편지/쓰다", "answer": "말로 하는 대신에 편지를 썼어요."}]}, {"num": 47, "term": "-(으)ㄴ/는 반면(에)", "meaning": "Trái lại, ngược lại (đối lập giữa hai vế)", "blocks": [["p", "Thể hiện mệnh đề trước và mệnh đề sau là các thực tế đối lập/trái ngược nhau."], ["ex", "연아네 회사는 업무량은 <b>적은 반면에</b> 월급은 많다.", "Công ty của Yeon-ah khối lượng công việc thì ít nhưng ngược lại lương lại cao."], ["ex", "리카는 한국어를 <b>잘하는 반면에</b> 중국어는 못하는 편이다.", "Rika giỏi tiếng Hàn nhưng ngược lại tiếng Trung thì thuộc dạng kém."]], "practice": [{"vn": "Anh trai thì hoạt bát, trái lại em trai lại trầm tính.", "hint": "형/활발하다/동생/조용하다", "answer": "형은 활발한 반면에 동생은 조용해요."}, {"vn": "Vùng này mùa đông lạnh, trái lại mùa hè lại mát mẻ.", "hint": "지역/겨울/춥다/여름/시원하다", "answer": "이 지역은 겨울에 추운 반면에 여름에는 시원해요."}, {"vn": "Lương thì cao, trái lại công việc lại quá nhiều.", "hint": "월급/많다/일/너무/많다", "answer": "월급은 많은 반면에 일이 너무 많아요."}]}, {"num": 48, "term": "-(으)ㄴ/는데", "meaning": "Nhưng, mà (nêu bối cảnh/hoàn cảnh dẫn dắt cho vế sau)", "blocks": [["p", "<b>1. Giải thích tình huống, chuyển cảnh: Rất hay dùng khi bắt đầu cuộc hội thoại hoặc khi muốn đổi chủ đề một cách nhẹ nhàng.</b>"], ["ex", "오늘 내 <b>생일인데</b> 우리 집에 놀러 와.", "Hôm nay là sinh nhật tớ đấy, sang nhà tớ chơi đi."], ["ex", "감기에 <b>걸렸는데</b> 병원에 안 가요?", "Bị cảm rồi mà không đi bệnh viện sao?"], ["ex", "날씨가 <b>좋은데</b> 산에 갈까요?", "Thời tiết đẹp thế này, chúng mình đi núi nhé?"], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ/는데' và '-(으)니까'</b>", "<b>1. -(으)ㄴ/는데:</b> Nói trước về tình huống liên quan đến đối tượng", "để chuẩn bị đưa ra lời nói tiếp theo."]], ["ex", "날씨가 <b>좋은데</b> 산에 갈까요?", "→ Giải thích tình huống thời tiết đẹp rồi rủ đi núi."], ["bq", ["<b>2. -(으)니까:</b> Nhấn mạnh lời nói ở mệnh đề trước chính là nguyên", "nhân, căn cứ, tiền đề cho lời nói ở mệnh đề sau."]], ["ex", "날씨가 <b>좋으니까</b> 산에 갈까요?", "→ Lý do rủ đi núi là vì thời tiết đẹp."], ["p", "<b>2. So sánh: Có thể đổi vị trí mệnh đề trước và mệnh đề sau cho nhau.</b>"], ["ex", "키는 <b>큰데</b> 발은 작아요. (발은 작은데 키는 커요.)", "Chiều cao thì cao nhưng chân lại nhỏ. / Chân nhỏ nhưng chiều cao lại cao."], ["ex", "말하기는 <b>쉬운 데</b> 쓰기는 어려워요. (쓰기는 어려운 데 말하기는 쉬워요.)", "Nói thì dễ nhưng viết thì khó. / Viết thì khó nhưng nói thì dễ."], ["ex", "운동은 <b>잘하는데</b> 노래는 못해요. (노래는 못하는데 운동은 잘해요.)", "Tập thể thao thì giỏi nhưng hát thì kém. / Hát kém nhưng tập thể thao lại giỏi."], ["p", "<b>3. Tương phản/Đối chiếu: Kết quả ở mệnh đề sau xuất hiện trái ngược với kỳ vọng ở mệnh đề trước. Không thể đổi vị trí mệnh đề trước và mệnh đề sau.</b>"], ["ex", "항상 열심히 <b>공부하는데</b> 시험을 못 봐요.", "Lúc nào cũng học hành chăm chỉ nhưng thi cử lại kém."], ["ex", "좋아했던 사람이 <b>있었는데</b> 헤어졌어요.", "Đã từng có người tôi yêu thích nhưng chúng tôi đã chia tay rồi."]], "practice": [{"vn": "Thời tiết đẹp thế này, chúng ta đi leo núi nhé?", "hint": "날씨/좋다/등산/가다", "answer": "날씨가 좋은데 등산하러 갈까요?"}, {"vn": "Tôi thích đồ ăn cay nhưng chồng tôi lại không ăn được.", "hint": "매운 음식/좋아하다/남편/못 먹다", "answer": "저는 매운 음식을 좋아하는데 남편은 못 먹어요."}, {"vn": "Bây giờ ngoài trời đang mưa đấy, bạn có ô không?", "hint": "밖/비/오다/우산/있다", "answer": "지금 밖에 비가 오는데 우산 있으세요?"}]}, {"num": 49, "term": "-(으)ㄴ/는데도", "meaning": "Mặc dù... nhưng vẫn (nhượng bộ, thể hiện điều bất ngờ)", "blocks": [["p", "Là cấu trúc ghép thêm '도' (cũng/ngay cả) mang tính nhấn mạnh vào cấu trúc đối chiếu '-(으)ㄴ/는데'. Dùng khi người nói muốn nhấn mạnh hơn nữa ý nghĩa đối chiếu, tương phản."], ["ex", "열심히 <b>운동하는데도</b> 살을 못 빼요.", "Mặc dù tập thể dục rất chăm chỉ nhưng tôi vẫn không giảm được cân."], ["ex", "시간이 <b>많았는데도</b> 아무것도 못 했어요.", "Mặc dù có nhiều thời gian nhưng tôi vẫn chẳng làm được gì."]], "practice": [{"vn": "Mặc dù đã học chăm chỉ nhưng điểm vẫn không tăng.", "hint": "열심히/공부하다/성적/오르다", "answer": "열심히 공부했는데도 성적이 오르지 않았어요."}, {"vn": "Mặc dù đã uống thuốc nhưng sốt vẫn không hạ.", "hint": "약/먹다/열/떨어지다", "answer": "약을 먹었는데도 열이 안 떨어져요."}, {"vn": "Mặc dù đã giải thích nhiều lần nhưng vẫn không hiểu.", "hint": "여러 번/설명하다/이해하다", "answer": "여러 번 설명했는데도 이해를 못 해요."}]}, {"num": 50, "term": "-(으)ㄴ즉", "meaning": "Xét thấy, nếu xét... thì (văn viết trang trọng, cổ điển)", "blocks": [["p", "Thể hiện mệnh đề trước trở thành lý do hoặc điều kiện cho mệnh đề sau."], ["ex", "튀어가 <b>본즉</b> 그는 병원으로 실려 가고 있었다.", "Chạy lại xem thử thì anh ấy đang được đưa đi bệnh viện rồi."], ["ex", "내가 <b>물은즉</b> 그는 마지못해 대답을 했다.", "Tôi hỏi thì anh ấy mới miễn cưỡng trả lời."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄴ즉' và '-(으)니까'</b>", "<b>1.</b> '-(으)ㄴ즉' có thể thay đổi bằng '-(으)니까'. '-(으)니까' hay", "dùng trong văn nói, còn '-(으)ㄴ즉' phù hợp với từ hán tự và văn phong", "trang trọng, chuẩn mực."]], ["ex", "모든 문제는 자신에게 <b>달린즉</b> 자신이 달라지면 문제는 해결될 것이다. → 모든 문제는 자신에게 <b>달렸으니까</b> 자신이 달라지면 문제는 해결될 것이다.", "Mọi vấn đề đều phụ thuộc vào bản thân nên nếu bản thân thay đổi thì vấn đề sẽ được giải quyết."], ["bq", ["<b>2.</b> Khi kết hợp với danh từ thành dạng <b>'-인즉'</b>, nó mang nghĩa", "'không phải cái gì khác mà chính là/nếu nói là...', dùng để nêu ra", "chủ đề (có thể thay bằng tiểu từ '는/은')."]], ["ex", "<b>사실인즉</b> 옳으신 말씀이지만 그렇게 하기에는 어렵습니다. → <b>사실은</b> 옳으신 말씀이지만 그렇게 하기에는 어렵습니다.", "Nói thực ra thì lời ngài nói là đúng, nhưng làm như thế thì rất khó."]], "practice": [{"vn": "Xét thấy tình hình như vậy nên tôi đành phải đồng ý.", "hint": "사정/그러하다/어쩔 수 없이/동의하다", "answer": "사정이 그러한즉 어쩔 수 없이 동의했다."}, {"vn": "Xét thấy lý lẽ như vậy nên không thể phản bác được.", "hint": "이치/이러하다/반박하다", "answer": "이치가 이러한즉 반박할 수가 없었다."}, {"vn": "Xét thấy tình hình nghiêm trọng nên phải lập tức đưa ra đối sách.", "hint": "사태/심각하다/즉시/대책/세우다", "answer": "사태가 심각한즉 즉시 대책을 세워야 한다."}]}, {"num": 51, "term": "-(으)ㄹ 만큼", "meaning": "Đến mức, chừng nào (mức độ tương xứng)", "blocks": [["p", "<b>1. Thể hiện ý nghĩa 'với số lượng/mức độ giống như cái đó', 'giống như cái đó'.</b>"], ["ex", "음식을 <b>먹을 만큼</b> 가져가세요.", "Hãy lấy thức ăn vừa đủ lượng mình sẽ ăn."], ["ex", "죽을 때까지 쓸 수 <b>있을 만큼</b> 돈을 벌고 싶어요.", "Tôi muốn kiếm tiền nhiều đến mức có thể tiêu đến tận lúc chết."], ["ex", "선생님, 숙제를 할 수 <b>있을 만큼</b> 주세요.", "Thầy/cô ơi, xin hãy cho bài tập về nhà ở mức chúng em có thể làm được thôi ạ."], ["p", "<b>2. '-(으)ㄴ/는 만큼' cũng dùng để thể hiện mệnh đề trước là lý do hoặc căn cứ của mệnh đề sau.</b>"], ["ex", "시간이 <b>이른 만큼</b> 식사보다는 차를 마셨으면 좋겠어요.", "Vì thời gian còn sớm nên thay vì ăn cơm, tôi muốn uống trà hơn."], ["ex", "나는 <b>아는 만큼</b> 느낄 뿐이고, <b>느낀 만큼</b> 보인다는 말을 좋아한다.", "Tôi thích câu nói \"Bạn chỉ cảm nhận được nhiều như những gì bạn biết, và nhìn thấy được nhiều như những gì bạn cảm nhận\"."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 만큼' và '-(으)ㄹ 정도'</b>"]], ["ex", "배고파서 쓰러질 <b>만큼이다</b>. (X)", ""], ["ex", "배고파서 쓰러질 <b>정도이다</b>. (O)", "Đói đến mức muốn gục ngã."], ["bq", ["'-(으)ㄹ 정도' và '-(으)ㄹ 만큼' có nghĩa tương tự nhau nên nhiều", "trường hợp có thể thay đổi cho nhau. Tuy nhiên, cũng có trường hợp", "không thể thay '-(으)ㄹ 만큼' thành '-(으)ㄹ 정도'."]], ["p", "------------------------------------------------------------------------ <b>Cấu trúc</b>  <b>Ý nghĩa</b>               <b>Có thể đứng ở cuối câu không?</b> ------------- ------------------------- -------------------------------- <b>-(으)ㄹ     Giống như cái đó (Y hệt)  Không thể dùng 만큼</b>"], ["p", "<b>-(으)ㄹ     Tương tự như cái đó       Có thể dùng 정도</b> ------------------------------------------------------------------------"]], "practice": [{"vn": "Đó là câu chuyện cảm động đến mức khiến người ta rơi nước mắt.", "hint": "눈물/나다/감동적이다/이야기", "answer": "눈물이 날 만큼 감동적인 이야기였어요."}, {"vn": "Tôi đã cố gắng hết sức trong khả năng có thể.", "hint": "할 수 있다/최선/다하다", "answer": "할 수 있는 만큼 최선을 다했어요."}, {"vn": "Hãy ăn nhiều tùy theo mức bạn muốn ăn.", "hint": "먹다/싶다/드시다", "answer": "먹고 싶은 만큼 드세요."}]}, {"num": 52, "term": "-(으)ㄹ 뿐만 아니라", "meaning": "Không những... mà còn (nhấn mạnh mức độ tăng thêm)", "blocks": [["p", "Thể hiện ý nghĩa 'không chỉ dừng lại ở lời nói/sự việc phía trước mà còn cộng thêm cả những gì lời nói/sự việc phía sau chỉ đến'."], ["p", "<b>1. Khi '뿐' dùng như một danh từ phụ thuộc: Gắn vào động từ hành động, động từ trạng thái, '이다' dưới dạng '-(으)ㄹ 뿐(만) 아니라'. Nếu mệnh đề trước là tích cực thì mệnh đề sau cũng tích cực, nếu mệnh đề trước là tiêu cực thì mệnh đề sau cũng là tiêu cực.</b>"], ["ex", "정은이는 마음이 <b>고울 뿐 아니라</b> 능력도 좋아요.", "Jeong-eun không những có tâm hồn đẹp mà năng lực cũng tốt."], ["ex", "그 식당은 음식이 <b>맛있을 뿐 아니라</b> 종업원도 친절합니다.", "Nhà hàng đó không những thức ăn ngon mà nhân viên cũng thân thiện."], ["p", "<b>2. Khi '뿐' dùng như một trợ từ: Gắn trực tiếp vào danh từ dưới dạng '~뿐(만) 아니라'.</b>"], ["ex", "<b>점심뿐만 아니라</b> 아침도 굶었어요.", "Không chỉ bữa trưa mà bữa sáng tôi cũng bỏ đói."], ["ex", "<b>방청소뿐만 아니라</b> 옷장 청소도 했어요.", "Không chỉ dọn dẹp phòng mà tôi còn dọn dẹp cả tủ quần áo nữa."]], "practice": [{"vn": "Anh ấy không những thông minh mà còn chăm chỉ nữa.", "hint": "똑똑하다/성실하다", "answer": "그는 똑똑할 뿐만 아니라 성실하기도 하다."}, {"vn": "Bộ phim này không những thú vị mà còn mang lại bài học.", "hint": "영화/재미있다/교훈/주다", "answer": "이 영화는 재미있을 뿐만 아니라 교훈도 준다."}, {"vn": "Tôi không chỉ học tiếng Hàn mà còn học cả tiếng Nhật.", "hint": "한국어/일본어/공부하다", "answer": "저는 한국어뿐만 아니라 일본어도 공부해요."}]}, {"num": 53, "term": "-(으)ㄹ 텐데", "meaning": "Chắc là sẽ... đấy (nhưng), dự đoán kèm gợi ý/lo lắng ở vế sau", "blocks": [["p", "Dự đoán [-(으)ㄹ 테] + Tình huống [-(으)ㄴ데]: Chủ ngữ ở mệnh đề sau có thể giống hoặc khác với mệnh đề trước."], ["ex", "시험이 <b>어려울 텐데</b> 열심히 공부해야 해요.", "Kỳ thi chắc là sẽ khó đấy nên phải học hành chăm chỉ vào."], ["ex", "친구들이 <b>기다릴 텐데</b> 빨리 가 보세요.", "Các bạn chắc là đang chờ đấy, hãy mau đi xem sao."], ["bq", ["<b>Tìm hiểu thêm | So sánh '-(으)ㄹ 텐데' và '-(으)ㄹ 테니까'</b>", "<b>1. -(으)ㄹ 텐데:</b> Dùng khi vừa thể hiện sự dự đoán mạnh mẽ của", "người nói về lời nói đứng trước, vừa tiếp nối nói nội dung có liên", "quan đến nó."]], ["ex", "차가 <b>막힐 텐데</b> 지하철을 탑시다.", "Xe chắc là sẽ tắc đấy, chúng ta đi tàu điện ngầm đi."], ["ex", "차가 <b>막힐 텐데</b> 어떡하지요?", "Xe chắc là sẽ tắc đấy, phải làm sao đây?"], ["bq", ["<b>2. -(으)ㄹ 테니까:</b> Dùng khi nhấn mạnh lời nói đứng trước chính là", "điều kiện cho lời nói đứng sau. Khi đặt câu hỏi (câu nghi vấn),", "<b>không thể</b> dùng '-(으)ㄹ 테니까'."]], ["ex", "차가 <b>막힐 테니까</b> 지하철을 탑시다. (O)", "Vì xe chắc chắn sẽ tắc nên chúng ta hãy đi tàu điện ngầm."], ["ex", "차가 막힐 테니까 어떡하지요? (X)", ""], ["p", "------------------------------------------------------------------------ <b>Cấu       </b>Cấu tạo<b>    </b>Ý nghĩa<b>          </b>Có dùng trong câu hỏi trúc<b>                                          được không?</b> ----------- -------------- -------------------- ------------------------ <b>-(으)ㄹ   -(으)ㄹ 테 +   Nói về tình huống dự Có thể dùng (◯) 텐데</b>      -(으)ㄴ데      đoán"], ["p", "<b>-(으)ㄹ   -(으)ㄹ 테 +   Nói về lý do/điều    Không thể dùng (×) 테니까</b>    -(으)니까      kiện dự đoán ------------------------------------------------------------------------"]], "practice": [{"vn": "Trời chắc sẽ mưa đấy, hãy mang theo ô.", "hint": "비/오다/우산/챙기다", "answer": "비가 올 텐데 우산을 챙기세요."}, {"vn": "Chắc bạn mệt lắm đấy, hãy nghỉ ngơi một chút.", "hint": "많이/피곤하다/좀/쉬다", "answer": "많이 피곤할 텐데 좀 쉬세요."}, {"vn": "Đường chắc sẽ tắc đấy, hãy xuất phát sớm.", "hint": "길/막히다/일찍/출발하다", "answer": "길이 막힐 텐데 일찍 출발합시다."}]}, {"num": 54, "term": "-(으)ㄹ까 봐(서)", "meaning": "Vì sợ rằng, e rằng (lo lắng nên làm gì đó để tránh)", "blocks": [["p", "Thể hiện sự lo lắng, e ngại rằng hành động đó sẽ phát sinh hoặc sẽ rơi vào tình huống như vậy."], ["ex", "결혼식에 비가 <b>올까 봐</b> 걱정했어요.", "Tôi đã lo lắng vì sợ trời sẽ mưa vào lễ cưới."], ["ex", "어른 앞에서 <b>실수할까 봐</b> 얼마나 긴장했는지 몰라요.", "Không biết tôi đã căng thẳng thế nào vì sợ sẽ mắc lỗi trước mặt người lớn."]], "practice": [{"vn": "Vì sợ trời mưa nên tôi đã mang theo ô.", "hint": "비/오다/우산/챙기다", "answer": "비가 올까 봐서 우산을 챙겼어요."}, {"vn": "Vì sợ bị trễ nên tôi đã vội vàng xuất phát.", "hint": "늦다/서두르다/출발하다", "answer": "늦을까 봐서 서둘러 출발했어요."}, {"vn": "Vì sợ đứa trẻ bị thương nên tôi đã theo dõi liên tục.", "hint": "아이/다치다/계속/지켜보다", "answer": "아이가 다칠까 봐서 계속 지켜봤어요."}]}, {"num": 55, "term": "-(으)ㄹ라치면", "meaning": "Mỗi khi định... thì (điều kiện lặp lại, cổ điển/ít dùng)", "blocks": [["p", "Dùng khi giả định một cách trừu tượng về sự việc đã trải qua vài lần."], ["ex", "잘 놀다가도 엄마가 밖에 <b>나갈라치면</b> 아기가 울더군요.", "Đang chơi ngoan là thế mà cứ hễ mẹ định đi ra ngoài là em bé lại khóc."], ["ex", "비가 <b>올라치면</b> 반드시 먹구름이 끼어요.", "Cứ hễ trời sắp mưa là nhất định mây đen sẽ kéo đến."]], "practice": [{"vn": "Mỗi khi định rời đi thì trời lại luôn đổ mưa.", "hint": "떠나다/항상/비/오다", "answer": "떠나려니까 항상 비가 왔다."}, {"vn": "Mỗi khi định nói thì cổ họng lại nghẹn lại.", "hint": "말/하다/목/메다", "answer": "말을 하려니까 목이 메었다."}, {"vn": "Mỗi khi định quên thì lại cứ nhớ đến.", "hint": "잊다/자꾸/생각/나다", "answer": "잊으려니까 자꾸 생각이 났다."}]}, {"num": 56, "term": "-(으)ㄹ뿐더러", "meaning": "Không những... mà còn (tương tự '-(으)ㄹ 뿐만 아니라' nhưng trang trọng hơn)", "blocks": [["p", "Thể hiện ý nghĩa 'không chỉ là thực tế ở mệnh đề trước mà cộng thêm vào đó, thực tế ở mệnh đề sau cũng như vậy'. Lúc này, nếu động từ đi trước thể hiện sự tích cực thì động từ đi sau cũng thể hiện sự tích cực, nếu động từ đi trước thể hiện sự tiêu cực thì động từ đi sau cũng thể hiện sự tiêu cực."], ["ex", "그 선수는 개인 기술이 <b>좋을뿐더러</b> 체력도 강합니다.", "Vận động viên đó không những kỹ thuật cá nhân tốt mà thể lực cũng mạnh mẽ."], ["ex", "신인 가수가 노래를 잘 <b>불렀을뿐더러</b> 춤 솜씨도 대단했습니다.", "Ca sĩ tân binh đó không những hát hay mà vũ đạo cũng rất tuyệt vời."]], "practice": [{"vn": "Anh ấy không những chăm chỉ mà năng lực còn xuất sắc nữa.", "hint": "부지런하다/능력/뛰어나다", "answer": "그는 부지런할뿐더러 능력도 뛰어나다."}, {"vn": "Cuốn sách này không những bổ ích mà còn thú vị nữa.", "hint": "책/유익하다/재미/있다", "answer": "이 책은 유익할뿐더러 재미도 있다."}, {"vn": "Bộ phim đó không những cảm động mà diễn xuất của diễn viên còn xuất sắc nữa.", "hint": "영화/감동적이다/배우들/연기/훌륭하다", "answer": "그 영화는 감동적일뿐더러 배우들의 연기도 훌륭했다."}]}, {"num": 57, "term": "-(으)ㄹ세라", "meaning": "Sợ rằng, e rằng (lo sợ điều gì xảy ra nên cẩn thận — cổ điển)", "blocks": [["p", "Thể hiện ý nghĩa mong sao không bị như thế, nhưng lại lo lắng sợ rằng biết đâu chừng sẽ trở nên như thế."], ["ex", "<b>늦을세라</b> 얼마나 열심히 달렸는지 몰라요.", "Tôi không biết là mình đã chạy bán sống bán chết thế nào vì sợ sẽ bị trễ."]], "practice": [{"vn": "Sợ đứa trẻ thức giấc nên tôi bước đi thật khẽ.", "hint": "아이/깨다/조용히/걷다", "answer": "아이가 깰세라 조용히 걸었다."}, {"vn": "Sợ người khác nghe thấy nên tôi đã hạ giọng.", "hint": "남/듣다/목소리/낮추다", "answer": "남이 들을세라 목소리를 낮췄다."}, {"vn": "Sợ đồ ăn bị nguội nên tôi đã vội mang đến ngay.", "hint": "음식/식다/서둘러/가져오다", "answer": "음식이 식을세라 서둘러 가져왔다."}]}, {"num": 58, "term": "-(으)ㄹ수록", "meaning": "Càng... càng (mức độ tăng dần theo)", "blocks": [["p", "<b>1. Thể hiện hành động hoặc trạng thái nào đó ngày càng tăng thêm/được cộng thêm.</b>"], ["ex", "한국말은 <b>공부할수록</b> 재미있습니다.", "Tiếng Hàn càng học càng thấy thú vị."], ["ex", "<b>바쁠수록</b> 운전을 조심해야 합니다.", "Càng bận rộn thì càng phải cẩn thận khi lái xe."], ["p", "<b>2. Kết hợp với '-(으)면' để thể hiện mức độ tăng thêm một cách mạnh mẽ hơn.</b>"], ["ex", "노래를 <b>들으면 들을수록</b> 새로운 느낌이 듭니다.", "Bài hát này càng nghe thì lại càng cảm thấy có một cảm giác mới mẻ."], ["ex", "여행을 <b>하면 할수록</b> 견문이 넓어집니다.", "Đi du lịch càng nhiều thì tầm mắt/kiến thức lại càng mở rộng."]], "practice": [{"vn": "Càng nghĩ thì càng thấy tức giận.", "hint": "생각하다/화/나다", "answer": "생각할수록 화가 났다."}, {"vn": "Càng lên cao thì không khí càng lạnh.", "hint": "높이/올라가다/공기/차갑다", "answer": "높이 올라갈수록 공기가 차가워진다."}, {"vn": "Càng luyện tập thì thực lực càng tiến bộ.", "hint": "연습하다/실력/늘다", "answer": "연습할수록 실력이 늘어요."}]}, {"num": 59, "term": "-(으)ㄹ진대", "meaning": "Nếu xét thấy... thì tất yếu (văn viết trang trọng, hiếm dùng)", "blocks": [["p", "Thừa nhận sự thật ở mệnh đề trước đương nhiên là sẽ như thế, đồng thời thể hiện sự thật ở mệnh đề trước trở thành căn cứ hoặc điều kiện cho lời nói ở mệnh đề sau."], ["ex", "나라를 사랑하고 <b>아낄진대</b> 어찌 군 복무를 마다하겠어요?", "Đã yêu và trân trọng đất nước thì cớ sao lại từ chối việc thực hiện nghĩa vụ quân sự chứ?"], ["ex", "지구의 앞날을 <b>걱정할진대</b> 환경 오염을 어찌 방관하겠어요.", "Đã lo lắng cho tương lai của Trái Đất thì cớ sao lại khoanh tay đứng nhìn ô nhiễm môi trường chứ."]], "practice": [{"vn": "Xét thấy tính mạng con người quý giá thì không được đối xử tùy tiện.", "hint": "사람/목숨/중하다/함부로/하다", "answer": "사람의 목숨이 중할진대 함부로 해서는 안 된다."}, {"vn": "Xét thấy chân lý là như vậy thì ai có thể phủ nhận được.", "hint": "진리/이러하다/부정하다", "answer": "진리가 이러할진대 누가 부정할 수 있으랴."}, {"vn": "Xét thấy tình hình cấp bách thì không có thời gian trì hoãn.", "hint": "사정/급하다/지체하다/시간", "answer": "사정이 급할진대 지체할 시간이 없다."}]}, {"num": 60, "term": "-(으)련마는/(으)련만", "meaning": "Đáng lẽ... nhưng (tiếc nuối, cổ điển)", "blocks": [["p", "<b>1. Dùng khi người nói dự đoán về một thực tế trong tương lai hoặc một thực tế mang tính giả định, mang nghĩa tương đương với '-겠지만' (nhưng/dù... nhưng).</b>"], ["ex", "건물 안에 매점도 <b>있으련마는</b> 눈에 띄지 않는군요.", "Trong tòa nhà chắc là cũng có cửa hàng tiện lợi đấy nhưng chẳng thấy đâu cả."], ["ex", "약을 먹었으면 <b>나으련만</b> 아직도 아프다고 합니다.", "Uống thuốc vào thì chắc là sẽ khỏi đấy nhưng nghe nói hiện tại vẫn còn đau."], ["p", "<b>2. Bổ sung '-(으)련만' vào cấu trúc thể hiện nguyện vọng '-(으)면 좋겠다' thành dạng '-(으)면 좋으련만'.</b>"], ["ex", "일이 잘 <b>해결되면 좋으련만</b> 안 될까 봐 걱정이 됩니다.", "Công việc nếu được giải quyết êm đẹp thì tốt biết mấy, nhưng tôi lại lo là sẽ không được."], ["ex", "주말에는 날씨가 <b>맑았으면 좋으련만</b> 어떨지 모르겠네요.", "Cuối tuần thời tiết nếu đẹp thì tốt biết mấy, nhưng không biết sẽ thế nào đây."]], "practice": [{"vn": "Đáng lẽ nên nghỉ ngơi một chút nhưng việc nhiều nên không nghỉ được.", "hint": "좀/쉬다/일/많다", "answer": "좀 쉬련마는 일이 많아서 쉴 수가 없다."}, {"vn": "Đáng lẽ muốn giúp đỡ nhưng vì không có khả năng nên tiếc nuối.", "hint": "돕다/싶다/능력/없다/안타깝다", "answer": "돕고 싶으련마는 능력이 없어서 안타깝다."}, {"vn": "Đáng lẽ muốn đi nhưng hoàn cảnh không cho phép.", "hint": "가다/싶다/형편/안 되다", "answer": "가고 싶으련마는 형편이 안 된다."}]}, {"num": 61, "term": "-(으)려거든", "meaning": "Nếu định/có ý muốn... thì (điều kiện cho ý định)", "blocks": [["p", "Có nghĩa là nếu muốn thực hiện ý đồ của chủ ngữ thì phải có điều kiện giống như ở mệnh đề sau."], ["ex", "라면을 <b>먹으려거든</b> 물을 끓여요.", "Nếu muốn ăn mì gói thì hãy nấu nước sôi đi."], ["ex", "의사가 <b>되려거든</b> 지금부터 열심히 공부를 해라.", "Nếu muốn trở thành bác sĩ thì từ bây giờ hãy học hành chăm chỉ vào."]], "practice": [{"vn": "Nếu có ý định thành công thì đừng từ bỏ.", "hint": "성공하다/포기하다", "answer": "성공하려거든 포기하지 마세요."}, {"vn": "Nếu định rời đi thì hãy đi ngay bây giờ.", "hint": "떠나다/지금", "answer": "떠나려거든 지금 떠나라."}, {"vn": "Nếu định học thì hãy học cho đến nơi đến chốn.", "hint": "배우다/제대로", "answer": "배우려거든 제대로 배워라."}]}, {"num": 62, "term": "-(으)려니와", "meaning": "Không những... mà còn (tương tự '-거니와' nhưng gắn vào động từ tương lai/ý chí)", "blocks": [["p", "Dùng khi muốn bổ sung thêm nội dung ở mệnh đề trước vào mệnh đề sau, mang ý nghĩa 'sự việc như thế là lẽ đương nhiên rồi, mà lại còn...' đối với sự việc trong tương lai hoặc sự việc mang tính giả định."], ["ex", "동대문 시장은 물건도 <b>많으려니와</b> 값도 쌉니다.", "Chợ Dongdaemun không những hàng hóa nhiều mà giá cả cũng rẻ."], ["ex", "그 여자는 마음씨도 <b>고우려니와</b> 부지런하기도 합니다.", "Người phụ nữ đó không những tấm lòng đẹp mà lại còn chăm chỉ nữa."]], "practice": [{"vn": "Việc này tuy khó khăn nhưng tôi nhất định sẽ làm được.", "hint": "이번 일/힘들다/반드시/해내다", "answer": "이번 일은 힘들려니와 반드시 해내겠습니다."}, {"vn": "Thời gian cũng không đủ nhưng tôi sẽ cố gắng hết sức.", "hint": "시간/부족하다/최선/다하다", "answer": "시간도 부족하려니와 최선을 다하겠습니다."}, {"vn": "Khó khăn tuy nhiều nhưng tôi sẽ không từ bỏ.", "hint": "어려움/많다/포기하다", "answer": "어려움이 많으려니와 포기하지 않겠습니다."}]}, {"num": 63, "term": "-(으)며", "meaning": "Vừa... vừa (hai hành động/trạng thái diễn ra đồng thời)", "blocks": [["p", "<b>1. Liệt kê: Liệt kê từ hai sự thật trở lên mà không liên quan đến thứ tự thời gian, do đó có thể đổi thứ tự giữa mệnh đề trước và mệnh đề sau. Có trường hợp chủ ngữ ở mệnh đề trước và sau giống nhau, cũng có trường hợp khác nhau. Có thể thay thế bằng '-고 (liệt kê)'. Chủ yếu dùng trong văn viết (문어체).</b>"], ["ex", "그 사람은 키가 <b>크며</b> 성격도 좋습니다.", "Người đó dáng cao mà tính cách cũng tốt."], ["ex", "부모님은 고향에 <b>계시며</b> 나는 한국에 삽니다.", "Bố mẹ tôi ở quê, còn tôi thì sống ở Hàn Quốc."], ["p", "<b>2. Hành động đồng thời: Dùng khi thực hiện hai việc cùng một lúc, do đó có thể đổi thứ tự giữa mệnh đề trước và mệnh đề sau. Chủ ngữ ở mệnh đề trước và sau giống nhau, có thể thay thế bằng '-(으)면서 (hành động đồng thời)'. Chủ yếu dùng trong văn viết (문어체).</b>"], ["ex", "동생이 음악을 <b>들으며</b> 공부합니다.", "Em tôi vừa nghe nhạc vừa học bài."], ["ex", "나는 텔레비전을 <b>보며</b> 식사를 해요.", "Tôi vừa xem tivi vừa ăn cơm."], ["ex", "언니가 학교에 <b>다니며</b> 회사에 다녔어요.", "Chị tôi vừa đi học vừa đi làm ở công ty."]], "practice": [{"vn": "Tôi vừa nghe nhạc vừa học bài.", "hint": "음악/듣다/공부하다", "answer": "음악을 들으며 공부해요."}, {"vn": "Chúng tôi vừa uống cà phê vừa trò chuyện.", "hint": "커피/마시다/이야기/나누다", "answer": "커피를 마시며 이야기를 나눴어요."}, {"vn": "Tôi vừa đi bộ vừa sắp xếp lại suy nghĩ.", "hint": "걷다/생각/정리하다", "answer": "걸으며 생각을 정리했어요."}]}, {"num": 64, "term": "-(이)랍시고", "meaning": "Tự cho mình là... (coi thường/mỉa mai việc ai đó tự nhận danh nghĩa gì đó)", "blocks": [["p", "Gắn vào danh từ, dùng khi coi thường, coi nhẹ một thực tế nào đó. Nếu âm cuối của danh từ đứng trước có phụ âm cuối (bachim) thì dùng <b>'-이랍시고'</b>, nếu không có phụ âm cuối thì dùng <b>'-랍시고'</b>."], ["ex", "자기가 <b>책임자랍시고</b> 일은 하지 않고 시키기만 한다.", "Tự cho mình là người chịu trách nhiệm/sếp nên chẳng chịu làm việc gì mà chỉ toàn sai bảo người khác."], ["ex", "나이 많은 <b>사람이랍시고</b> 아무에게나 반말하는 건 좋지 않아요.", "Cậy mình là người nhiều tuổi hơn rồi nói trống không với bất kỳ ai là điều không tốt."]], "practice": [{"vn": "Tự cho mình là người lớn nên nói năng tùy tiện với trẻ con.", "hint": "어른/아이/함부로/말하다", "answer": "자기가 어른이랍시고 아이에게 함부로 말한다."}, {"vn": "Tự cho mình là tiền bối nên chỉ toàn ra lệnh cho hậu bối.", "hint": "선배/후배/명령/하다", "answer": "선배랍시고 후배에게 명령만 한다."}, {"vn": "Tự cho mình là người có nhiều tiền nên coi thường người khác.", "hint": "돈/많다/사람/무시하다", "answer": "돈이 많다랍시고 사람을 무시한다."}]}];
